content[3]=[[["Peg came back from Lisbon on Friday night.", "Peg voltou de Lisboa na sexta à noite."], ["She bought some pretty jewels for Ava at the market.", "Ela comprou umas joias bonitas para a Ava no mercado."], ["Ava asked where she found them and how much they cost.", "Ava perguntou onde ela as achou e quanto custaram."], ["Peg paid one euro for each, in the local currency.", "Peg pagou um euro por cada uma, na moeda local."], ["The long voyage made her tired, so she took a taxi.", "A viagem longa a deixou cansada, então ela pegou um táxi."]], [["Where did you go on your trip?", "Aonde você foi na sua viagem?"], ["I went to Lisbon with my cousin.", "Fui a Lisboa com meu primo."], ["What did you buy at the market?", "O que você comprou no mercado?"], ["I bought some jewels and some fruit.", "Comprei umas joias e algumas frutas."], ["How did you get home from the airport?", "Como você voltou do aeroporto para casa?"], ["I took a taxi because my luggage was heavy.", "Peguei um táxi porque minha bagagem estava pesada."], ["How much did the taxi cost?", "Quanto custou o táxi?"], ["It cost twenty euros.", "Custou vinte euros."]], ["Entonação das perguntas com Wh-", "Nas perguntas com What, Where e How much, a voz sobe na palavra principal e desce no fim.", ["where", "Where did you go?"]], ["Where ___ you buy it?", "did", "do", "Onde você comprou isso?", "Pergunta no passado: Wh- + did + sujeito + verbo base."]];
