content[7]=[[["June used to live in a small village.", "June morava numa aldeia pequena antes."], ["Her parents used to keep cattle near the river.", "Os pais dela criavam gado perto do rio."], ["She used to wake up at five and feed a calf.", "Ela acordava às cinco e dava comida a um bezerro."], ["There was no bus, so she walked to school.", "Não havia ônibus, então ela ia a pé para a escola."], ["Now she lives in the city, but she misses the hills.", "Agora ela mora na cidade, mas sente falta das colinas."]], [["Did you use to live in a village?", "Você morava numa aldeia antes?"], ["Yes, I did. I used to live in a small hut.", "Sim. Eu morava numa cabana pequena."], ["What did you use to do every morning?", "O que você fazia toda manhã?"], ["I used to feed the chickens before school.", "Eu dava comida às galinhas antes da escola."], ["Did you use to play in the hills?", "Você brincava nas colinas?"], ["Yes, with my cousins every afternoon.", "Sim, com meus primos toda tarde."], ["Do you miss the village?", "Você sente falta da aldeia?"], ["Yes, I do. I used to be so happy there.", "Sinto. Eu era tão feliz lá."]], ["Used to: /juːst tə/", "Em used to, o d some e o s fica forte: “iust tu”. Não diga “iuzd”.", ["used to", "I used to run."]], ["I ___ live in a hut.", "used to", "use to", "Eu morava numa cabana pequena.", "No afirmativo, use used to; use to só aparece depois de did."]];
