content[9]=[[["When Ben was ten, his family visited a small island.", "Quando Ben tinha dez anos, a família dele visitou uma ilha pequena."], ["They took a boat early in the morning.", "Eles pegaram um barco de manhã cedo."], ["Ben used to be afraid of snakes, but he did not cry.", "Ben tinha medo de cobras, mas não chorou."], ["He saw turtles under a palm tree and smiled.", "Ele viu tartarugas debaixo de uma palmeira e sorriu."], ["He touched the skin of a turtle, and it was cool.", "Ele tocou na pele de uma tartaruga, e ela estava fria."]], [["What did you do on the island?", "O que você fez na ilha?"], ["We sat under a palm tree and watched turtles.", "Ficamos sentados debaixo de uma palmeira vendo tartarugas."], ["Did you take the boat alone?", "Você pegou o barco sozinho?"], ["No, I didn’t. My father came with me.", "Não. Meu pai foi comigo."], ["Where did you sleep?", "Onde vocês dormiram?"], ["We slept in a small hotel near the beach.", "Dormimos num hotel pequeno perto da praia."], ["Did you use to travel a lot?", "Você viajava muito?"], ["Not really. That was my first big trip.", "Nem tanto. Foi minha primeira viagem grande."]], ["Sons em palm e turtles", "Em palm, o l quase não soa: “pam”. Em turtles, o t inicial é forte e o final soa “ls”.", ["palm", "We sat under a palm."]], ["Ben ___ turtles under a palm.", "saw", "seed", "Ben viu tartarugas debaixo de uma palmeira.", "See é irregular: o passado é saw."]];
