content[11]=[[["Tina was working at the café on Friday morning.", "Tina estava trabalhando no café na sexta de manhã."], ["A man was waiting at the counter for his order.", "Um homem esperava no balcão pelo pedido dele."], ["Tina was making coffee, but the motor was making a strange noise.", "Tina fazia café, mas o motor fazia um barulho estranho."], ["The service was slow, so Lou was watching.", "O atendimento estava lento, então a Lou só olhava."], ["They were laughing when the man finally got his coffee.", "Elas riam quando o homem finalmente recebeu o café."]], [["Was the café busy on Friday?", "O café estava movimentado na sexta?"], ["Yes, it was. Many people were waiting.", "Estava. Muita gente esperava."], ["Were you working alone?", "Você estava trabalhando sozinha?"], ["No, I wasn’t. Lou was helping me.", "Não. A Lou estava me ajudando."], ["Was the customer angry?", "O cliente estava bravo?"], ["No, he wasn’t. He was waiting with a smile on his lips.", "Não. Ele esperava com um sorriso nos lábios."], ["Were you making his coffee?", "Você estava fazendo o café dele?"], ["Yes, I was. There was a long pause because of the motor.", "Estava. Houve uma longa pausa por causa do motor."]], ["Entonação de Yes/No questions", "Em perguntas de sim ou não, como Were you working?, a voz sobe no fim.", ["working", "Were you working?"]], ["___ you working alone?", "Were", "Was", "Você estava trabalhando sozinha?", "Com you, use were, mesmo no singular."]];
patterns[11]=new RegExp("\\b(Was|Were) \\w+ \\w+ing\\b.*\\?|\\bYes, I was\\b|\\bNo, I wasn\u2019t\\b","i");
themes[11]="chat";
photos[11]=["photo-counter-2.webp", "photo-restaurant-1.webp"];
plans[12]={"title": "Faxina com música", "file": "photo-entrance-1.webp", "grammar": "While + passado contínuo para duas ações ao mesmo tempo", "goal": "Use while + was/were + -ing para dizer que duas ações aconteciam ao mesmo tempo.", "words": [["maid", "faxineira"], ["pipes", "canos"], ["wheels", "rodas"], ["tube", "tubo"]]};
content[12]=[[["While Noah was taking out the garbage, Ava was cleaning the kitchen.", "Enquanto Noah tirava o lixo, Ava limpava a cozinha."], ["Their mother was cooking dinner while the music was playing.", "A mãe deles preparava o jantar enquanto a música tocava."], ["The maid was cleaning the pipes in the hall.", "A faxineira limpava os canos no corredor."], ["While everyone was working, Lou was singing loudly.", "Enquanto todos trabalhavam, Lou cantava bem alto."], ["The house was clean when their father came home.", "A casa estava limpa quando o pai chegou."]], [["What were you doing while I was shopping?", "O que você estava fazendo enquanto eu fazia compras?"], ["I was cleaning the kitchen with Ava.", "Eu estava limpando a cozinha com a Ava."], ["Was Noah helping you?", "O Noah estava ajudando você?"], ["Yes, he was taking out the garbage.", "Estava, ele tirava o lixo."], ["Who was playing the music?", "Quem estava tocando a música?"], ["Nico was. He was dancing with a mop!", "Era o Nico. Ele dançava com um esfregão!"], ["What was the maid doing?", "O que a faxineira fazia?"], ["She was cleaning the vacuum tube and its wheels.", "Ela limpava o tubo do aspirador e as rodas dele."]], ["While: /waɪl/", "Em while, o w é arredondado e o final é um l escuro, com a língua no céu da boca.", ["while", "While I was cooking, he sang."]], ["Ava was cleaning ___ Noah was cooking.", "while", "during", "Ava limpava enquanto Noah cozinhava.", "While liga duas ações seguidas de verbo; during vem com substantivo."]];
patterns[12]=new RegExp("\\bwhile\\b","i");
themes[12]="chat";
photos[12]=["photo-door-1.webp", "photo-coffeeTable-1.webp"];
plans[13]={"title": "O touro na estrada", "file": "photo-street-1.webp", "grammar": "Passado contínuo e passado simples juntos", "goal": "Use was/were + -ing para a ação longa e o passado simples para a interrupção: I was walking when…", "words": [["bicycle", "bicicleta"], ["bull", "touro"], ["nearby", "por perto"], ["bones", "ossos"]]};
content[13]=[[["Peg was riding her bicycle down a hill when a bull ran across the road.", "Peg descia uma ladeira de bicicleta quando um touro atravessou a estrada."], ["She stopped quickly, but she fell on the grass.", "Ela parou rápido, mas caiu na grama."], ["A man was walking nearby when he saw her.", "Um homem caminhava por perto quando a viu."], ["He helped her stand up while the bull ran away.", "Ele a ajudou a levantar enquanto o touro fugia."], ["Her knee hurt, but no bones were broken.", "O joelho dela doía, mas nenhum osso estava quebrado."]], [["What happened to your knee?", "O que aconteceu com o seu joelho?"], ["I was riding my bicycle when a bull ran out.", "Eu andava de bicicleta quando um touro saiu correndo."], ["Where were you riding?", "Por onde você andava?"], ["I was going down the hill near the school.", "Eu descia a ladeira perto da escola."], ["Did someone stop to help you?", "Alguém parou para ajudar você?"], ["Yes, a man was walking there, and he came quickly.", "Sim, um homem caminhava ali e veio rápido."], ["Are you okay now?", "Você está bem agora?"], ["Yes, the doctor checked my bones at the clinic.", "Estou, o médico examinou meus ossos na clínica."]], ["Ran e fell: sons curtos", "Em ran, o a soa como o é aberto de “pé”. Em fell, é o e de “ferro”, sem prolongar.", ["ran", "A dog ran out."]], ["I ___ home when it started to rain.", "was walking", "walked", "Eu voltava para casa a pé quando começou a chover.", "A ação em andamento fica no contínuo; a que interrompe, no passado simples."]];
patterns[13]=new RegExp("\\b(was|were) \\w+ing\\b.*\\bwhen\\b|\\bwhen\\b.*\\b(ran|saw|came)\\b","i");
themes[13]="health";
photos[13]=["photo-street-1.webp", "photo-clinic-1.webp"];
plans[14]={"title": "Barulho à meia-noite", "file": "photo-dusk2-1.webp", "grammar": "Negativa: was not / were not (wasn’t / weren’t) + -ing", "goal": "Use wasn’t e weren’t + -ing para dizer o que não estava acontecendo.", "words": [["rats", "ratos"], ["pub", "bar"], ["snoring", "ronco"], ["teeth", "dentes"]]};
content[14]=[[["Last night, Lou was not sleeping well; his teeth hurt.", "Ontem à noite, Lou não estava dormindo bem; os dentes dele doíam."], ["The rats in the wall weren’t sleeping either.", "Os ratos na parede também não estavam dormindo."], ["A loud song was coming from the pub.", "Uma música alta vinha do bar."], ["A man was snoring in the next room, but Lou wasn’t angry.", "Um homem roncava no quarto ao lado, mas Lou não estava bravo."], ["At midnight, the snoring stopped, and Lou finally slept.", "À meia-noite, o ronco parou, e Lou finalmente dormiu."]], [["Why weren’t you sleeping at midnight?", "Por que você não estava dormindo à meia-noite?"], ["I wasn’t sleeping because of the noise.", "Eu não estava dormindo por causa do barulho."], ["Were the guests having a party?", "Os hóspedes estavam dando uma festa?"], ["No, they weren’t. They were snoring loudly.", "Não. Eles estavam roncando alto."], ["Weren’t you closing the window?", "Você não estava fechando a janela?"], ["I wasn’t. It was too hot in my room.", "Não estava. Fazia calor demais no quarto."], ["Was anyone talking to them?", "Alguém estava falando com eles?"], ["No one was, and I wasn’t angry.", "Ninguém estava, e eu não estava bravo."]], ["Wasn’t e weren’t", "Em wasn’t, o z leva a um n curto: WÓ-znt. Em weren’t, fale WÉR-nt, sem vogal no meio do nt.", ["wasn’t", "I wasn’t sleeping."]], ["I ___ sleeping at midnight.", "wasn’t", "didn’t", "Eu não estava dormindo à meia-noite.", "Com was/were, a negativa é wasn’t/weren’t; did é só para o passado simples."]];
patterns[14]=new RegExp("\\b(wasn\u2019t|weren\u2019t|was not|were not)\\b","i");
themes[14]="health";
photos[14]=["photo-dusk2-1.webp", "photo-door-1.webp"];
plans[15]={"title": "A festa à fantasia", "file": "photo-friends-1.webp", "grammar": "Contar uma cena: what was happening at the party", "goal": "Descreva uma cena no passado com várias ações em andamento: was dancing, were laughing.", "words": [["wizard", "mago"], ["fairy", "fada"], ["tigers", "tigres"], ["dancing", "dança"]]};
content[15]=[[["At June’s party, everyone was wearing a costume.", "Na festa da June, todos usavam fantasia."], ["Tina was wearing a wizard hat and dancing in the living room.", "Tina usava um chapéu de mago e dançava na sala."], ["June was wearing fairy wings and putting dessert on the table.", "June usava asas de fada e colocava a sobremesa na mesa."], ["Lou was taking photos of two tigers on the sofa.", "Lou tirava fotos de dois tigres no sofá."], ["Nobody was sitting down because the music was great.", "Ninguém estava sentado porque a música estava ótima."]], [["What was happening at the party?", "O que estava acontecendo na festa?"], ["Everybody was dancing and laughing.", "Todo mundo dançava e ria."], ["Who was wearing the wizard hat?", "Quem usava o chapéu de mago?"], ["Tina was. Her costume was amazing!", "A Tina. A fantasia dela estava incrível!"], ["What were you doing at ten?", "O que você fazia às dez?"], ["I was helping Ben with the dessert.", "Eu ajudava o Ben com a sobremesa."], ["Were the neighbors enjoying it too?", "Os vizinhos também estavam curtindo?"], ["Yes, they were. They were singing in the garden.", "Sim. Eles cantavam no jardim."]], ["Ritmo em frases com -ing", "Em Tina was dancing, as palavras fortes são Tina e dancing. Was fica fraco e rápido.", ["dancing", "Tina was dancing."]], ["Tina ___ a wizard hat.", "was wearing", "wore", "Tina usava um chapéu de mago.", "Para descrever uma cena em andamento, use was + -ing."]];
patterns[15]=new RegExp("\\b(was|were) \\w+ing\\b","i");
themes[15]="park";
