plans[16]={"title": "Atrasado por causa das ovelhas", "file": "photo-stationSign-1.webp", "grammar": "Because/so em explicações sobre o que aconteceu", "goal": "Use because para dar o motivo e so para mostrar a consequência.", "words": [["flock", "rebanho"], ["vehicle", "veículo"], ["excuse", "desculpa"], ["mule", "mula"]]};
content[16]=[[["Ravi was late because a flock blocked the road.", "Ravi se atrasou porque um rebanho bloqueou a estrada."], ["He was in a vehicle, so he could not walk.", "Ele estava num veículo, então não podia ir a pé."], ["His phone had no battery, so he asked a farmer.", "O celular dele estava sem bateria, então ele pediu ajuda a um fazendeiro."], ["The farmer called Ava because Ravi knew her number.", "O fazendeiro ligou para a Ava porque Ravi sabia o número dela."], ["Ava was not angry because the excuse was true.", "Ava não ficou brava porque a desculpa era verdadeira."]], [["Why were you late this morning?", "Por que você se atrasou hoje de manhã?"], ["I was late because a flock blocked the road.", "Me atrasei porque um rebanho bloqueou a estrada."], ["Why didn’t you call me?", "Por que você não me ligou?"], ["My phone had no battery, so I could not call.", "Meu celular estava sem bateria, então não pude ligar."], ["How did you get here?", "Como você chegou aqui?"], ["A farmer with a mule helped me, so I called you from his phone.", "Um fazendeiro com uma mula me ajudou, então liguei do telefone dele."], ["Is that really your excuse?", "É essa mesmo a sua desculpa?"], ["Yes, it is true, and I am very sorry.", "Sim, é verdade, e eu sinto muito."]], ["Because: /bɪˈkɒz/", "Em because, a sílaba fraca vem primeiro e a força cai em -cause, como “bicóz”.", ["because", "I stayed because it rained."]], ["I was late ___ the road was full of sheep.", "because", "so", "Me atrasei porque a estrada estava cheia de ovelhas.", "Because introduz o motivo; so introduz o resultado."]];
patterns[16]=new RegExp("\\b(because|so)\\b","i");
themes[16]="city";
photos[16]=["photo-stationSign-1.webp", "photo-phone-1.webp"];
plans[17]={"title": "Acampando perto do rio", "file": "photo-lake-1.webp", "grammar": "Then, after that, suddenly para narrar", "goal": "Use first, then, after that e suddenly para contar uma história em ordem.", "words": [["stars", "estrelas"], ["coal", "carvão"], ["suddenly", "de repente"], ["camping", "acampamento"]]};
content[17]=[[["First, Ben and Nico put up the tent near the river.", "Primeiro, Ben e Nico montaram a barraca perto do rio."], ["Then they made a fire with coal and cooked some potatoes.", "Depois fizeram uma fogueira com carvão e cozinharam batatas."], ["After that, they were sitting and watching the stars.", "Depois disso, ficaram sentados olhando as estrelas."], ["Suddenly, the light went out, and they heard a noise.", "De repente, a luz apagou, e eles ouviram um barulho."], ["It was only a small dog, so they laughed.", "Era só um cachorro pequeno, então eles riram."]], [["What happened first on your camping trip?", "O que aconteceu primeiro na viagem de camping?"], ["First, we put up the tent by the river.", "Primeiro, montamos a barraca perto do rio."], ["What did you do then?", "O que vocês fizeram depois?"], ["Then we made a fire with coal and ate dinner.", "Depois fizemos uma fogueira com carvão e jantamos."], ["What happened after that?", "O que aconteceu depois disso?"], ["Suddenly, my flashlight went out.", "De repente, minha lanterna apagou."], ["Were you afraid?", "Vocês ficaram com medo?"], ["Yes, but it was only a dog, so we laughed.", "Sim, mas era só um cachorro, então rimos."]], ["Suddenly: /ˈsʌdənli/", "Em suddenly, a força cai em SUD. O -den- é curto, quase só um d e um n: SÃ-dn-li.", ["suddenly", "Suddenly, it stopped."]], ["___, the light went out.", "Suddenly", "Sudden", "De repente, a luz apagou.", "Para modificar a frase toda, use o advérbio suddenly, com -ly."]];
patterns[17]=new RegExp("\\b(First|Then|After that|Suddenly)\\b","i");
themes[17]="park";
photos[17]=["photo-lake-1.webp", "photo-stationPark-1.webp"];
extras[17]={"camping": ["We love camping in summer.", "Nós adoramos acampar no verão."]};
plans[18]={"title": "Onde você estava às nove?", "file": "photo-ticketdesk-2.webp", "grammar": "Alibi e testemunha: where were you at nine?", "goal": "Pergunte e responda sobre onde alguém estava e o que fazia: Where were you at nine?", "words": [["thief", "ladrão"], ["alibi", "álibi"], ["jail", "cadeia"], ["prison", "prisão"]]};
content[18]=[[["Someone took Peg’s bicycle from the park at nine o’clock.", "Alguém levou a bicicleta da Peg do parque às nove horas."], ["A detective asked Tina, “Where were you at nine?”", "Um detetive perguntou à Tina: “Onde você estava às nove?”"], ["Tina said she was eating breakfast with Ben.", "Tina disse que tomava café da manhã com o Ben."], ["Ben was her alibi because he was sitting next to her.", "Ben era o álibi dela porque estava sentado ao lado dela."], ["A boy was riding the bicycle, so the detective found the thief.", "Um menino andava na bicicleta, então o detetive achou o ladrão."]], [["Where were you at nine last night?", "Onde você estava às nove ontem à noite?"], ["I was at the library with Ava.", "Eu estava na biblioteca com a Ava."], ["What were you doing there?", "O que você fazia lá?"], ["I was studying for a test.", "Eu estudava para uma prova."], ["Was anyone with you?", "Alguém estava com você?"], ["Yes, Ava was. She is my alibi, so I am not going to jail.", "Sim, a Ava. Ela é meu álibi, então não vou para a cadeia."], ["Were you at the library at ten too?", "Você ainda estava na biblioteca às dez?"], ["Yes, we were. Nobody goes to prison for studying!", "Estava. Ninguém vai para a prisão por estudar!"]], ["Where were you: ritmo", "Na fala rápida, Where were you soa “uér-uér-iu”. Só where e you recebem força.", ["where", "Where were you?"]], ["Where ___ you at nine?", "were", "was", "Onde você estava às nove?", "Com you, o passado de be é were."]];
patterns[18]=new RegExp("\\b[Ww]here (were|was) \\w+|\\b(was|were) \\w+ing\\b","i");
themes[18]="chat";
photos[18]=["photo-ticketdesk-2.webp", "photo-bag-1.webp"];
plans[19]={"title": "O dia do apagão", "file": "photo-dusk-1.webp", "grammar": "Revisão: passado contínuo, when, while, because e so", "goal": "Conte uma noite sem luz usando passado contínuo junto com passado simples, while, because e so.", "words": [["riddle", "charada"], ["glow", "brilho"], ["petrol", "gasolina"], ["darkness", "escuridão"]]};
content[19]=[[["There was a blackout in Lia’s street on Tuesday.", "Houve um apagão na rua da Lia na terça."], ["She was cooking dinner when the power went out.", "Ela preparava o jantar quando a energia acabou."], ["A soft glow came from an old petrol lamp.", "Um brilho suave vinha de uma velha lamparina a gasolina."], ["Her brother was telling a riddle while she cooked.", "O irmão dela contava uma charada enquanto ela cozinhava."], ["They were not worried; the darkness was almost fun.", "Eles não estavam preocupados; a escuridão era quase divertida."]], [["What were you doing when the power went out?", "O que você fazia quando a energia acabou?"], ["I was cooking dinner. It was suddenly dark.", "Eu cozinhava o jantar. De repente, ficou escuro."], ["Was your brother helping you?", "Seu irmão estava ajudando você?"], ["No, he wasn’t. He was telling a riddle.", "Não. Ele estava contando piadas."], ["How long did you wait for the power?", "Quanto tempo vocês esperaram a energia?"], ["We waited two hours because the blackout was big.", "Esperamos duas horas porque o apagão foi grande."], ["Did you eat in the dark?", "Vocês jantaram no escuro?"], ["Yes, we did. We ate by the glow of the lamp.", "Sim. Comemos à luz da lamparina."]], ["Blackout: acento na primeira sílaba", "Em blackout, a força cai em BLACK: BLÉC-aut. Em power, o som é quase uma sílaba só: “páuer”.", ["blackout", "The blackout was long."]], ["She ___ dinner when the power went out.", "was cooking", "cooked", "Ela preparava o jantar quando a energia acabou.", "A ação longa vai no contínuo, e a interrupção, no passado simples."]];
patterns[19]=new RegExp("\\b(was|were) \\w+ing\\b|\\bwhen\\b","i");
themes[19]="city";
photos[19]=["photo-dusk-1.webp", "photo-lake-2.webp"];
stories[19]=["A noite sem luz de Lia", "There was a blackout in Lia’s street on Tuesday evening.~Houve um apagão na rua da Lia na terça à noite.|She was cooking soup when the power suddenly went out.~Ela fazia sopa quando a energia acabou de repente.|The darkness was total, so she asked her brother for help.~A escuridão era total, então ela pediu ajuda ao irmão.|He was telling a riddle, but his phone had no battery.~Ele contava uma charada, mas o celular estava sem bateria.|While they looked for a lamp, someone knocked on the door.~Enquanto procuravam uma lamparina, alguém bateu à porta.|It was a neighbor, and she was holding an old petrol lamp.~Era uma vizinha, e ela segurava uma velha lamparina a gasolina.|A warm glow filled the kitchen, and they did not worry.~Um brilho quente encheu a cozinha, e eles não se preocuparam.|Then they sat outside and talked while the soup was cooling.~Depois sentaram lá fora e conversaram enquanto a sopa esfriava.|At eleven, the lights came back, and everybody cheered loudly.~Às onze, a luz voltou, e todos comemoraram bem alto.|Lia was tired, so she washed the pot and went to bed.~Lia estava cansada, então lavou a panela e foi dormir."];
plans[20]={"title": "Dois sofás na loja", "file": "photo-coffeeTable-1.webp", "grammar": "Comparativo curto: bigger than, cheaper than, earlier than", "goal": "Some -er ao adjetivo curto e use than para comparar duas coisas.", "words": [["couch", "sofá"], ["living room", "sala"], ["colour", "cor"], ["shape", "formato"]]};
content[20]=[[["Ravi is looking at two sofas in a store.", "Ravi está olhando dois sofás em uma loja."], ["The blue sofa is bigger than the gray one.", "O sofá azul é maior que o cinza."], ["The gray sofa is cheaper than the blue one.", "O sofá cinza é mais barato que o azul."], ["His living room is smaller than the store.", "A sala dele é menor que a loja."], ["He buys the gray couch and takes it home.", "Ele compra o sofá cinza e leva para casa."]], [["Which couch do you like more?", "De qual sofá você gosta mais?"], ["I like the blue one, but it is bigger than our room.", "Eu gosto do azul, mas ele é maior que nossa sala."], ["The gray one is smaller, and its shape is nicer.", "O cinza é menor, e o formato dele é mais bonito."], ["Yes, and it is cheaper than the blue one. I like the colour too.", "Sim, e é mais barato que o azul. Gosto da cor também."], ["How much is the gray sofa?", "Quanto custa o sofá cinza?"], ["It is three hundred dollars, with free delivery.", "São trezentos dólares, com entrega grátis."], ["Can you bring it on Saturday morning?", "Vocês podem trazer no sábado de manhã?"], ["Yes, we can come earlier than ten o’clock.", "Sim, podemos chegar antes das dez horas."]], ["O som /ð/ em than", "Ponha a ponta da língua entre os dentes e vibre a voz, como no th de this.", ["than", "The sofa is bigger than the chair."]], ["The gray sofa is ___ than the blue one.", "cheaper", "more cheap", "O sofá cinza é mais barato que o azul.", "Adjetivo curto recebe -er: cheap vira cheaper."]];
patterns[20]=new RegExp("\\b(?:bigger|smaller|cheaper|earlier) than\\b","i");
themes[20]="city";
photos[20]=["photo-coffeeTable-1.webp", "photo-counter-1.webp"];
plans[21]={"title": "Escolhendo uma poltrona", "file": "photo-desk-1.webp", "grammar": "More + adjetivo longo: more expensive, more comfortable", "goal": "Use more antes de adjetivos longos e than para comparar, sem juntar -er.", "words": [["armchair", "poltrona"], ["modern", "moderno"], ["cushion", "almofada"], ["covers", "capas"]]};
content[21]=[[["Tina wants a new armchair for her bedroom.", "Tina quer uma poltrona nova para o quarto dela."], ["The red armchair is more comfortable than the black one.", "A poltrona vermelha é mais confortável que a preta."], ["The black one is more modern, but it is more expensive.", "A preta é mais moderna, mas é mais cara."], ["She sits in both chairs and tests each cushion.", "Ela senta nas duas poltronas e testa cada almofada."], ["In the end, she picks the more comfortable chair.", "No fim, ela escolhe a poltrona mais confortável."]], [["Are you ready to choose an armchair?", "Você já está pronta para escolher uma poltrona?"], ["Almost. The red one is more comfortable.", "Quase. A vermelha é mais confortável."], ["But the black one is more modern.", "Mas a preta é mais moderna."], ["True, but it is much more expensive.", "É verdade, mas é muito mais cara."], ["How much more expensive is it?", "Quanto mais cara ela é?"], ["It costs fifty dollars more than the red one.", "Custa cinquenta dólares a mais que a vermelha."], ["Then I will take the red armchair.", "Então vou levar a poltrona vermelha."], ["Great choice. Do you want extra covers for it?", "Ótima escolha. Você quer capas extras para ela?"]], ["Acento em comfortable", "A sílaba forte é COM: COM-fer-ta-bol, e o meio quase some.", ["comfortable", "This bed is comfortable."]], ["The red armchair is ___ than the black one.", "more comfortable", "comfortabler", "A poltrona vermelha é mais confortável que a preta.", "Adjetivo longo usa more, não -er."]];
patterns[21]=new RegExp("\\bmore (?:comfortable|modern|expensive)\\b","i");
themes[21]="city";
