content[22]=[[["Noah and Ava read a book about mountains.", "Noah e Ava leem um livro sobre montanhas."], ["Mount Everest is the tallest mountain in the world.", "O Everest é a montanha mais alta do mundo."], ["The oldest mountain in the book is in Africa.", "A montanha mais velha do livro fica na África."], ["It also has the longest river in the story.", "Também tem o rio mais longo da história."], ["Ava loves climbing and wants the smallest mountain first.", "Ava adora escalar e quer primeiro a menor montanha."]], [["What is the tallest mountain you know?", "Qual é a montanha mais alta que você conhece?"], ["I know Everest. It is the tallest of all.", "Eu conheço o Everest. É a mais alta de todas."], ["Is it also the oldest mountain?", "Ela também é a montanha mais velha?"], ["No, there are older mountains in other places.", "Não, há montanhas mais velhas em outros lugares."], ["Which mountain is the easiest to climb?", "Qual montanha é a mais fácil de subir?"], ["The smallest one near our town is easy.", "A menor perto da nossa cidade é fácil."], ["Do you want to climb it this weekend?", "Você quer subir nela neste fim de semana?"], ["Yes, but the weather must be the best.", "Sim, mas o tempo precisa estar o melhor possível."]], ["Final -est em tallest", "Diga /ɪst/, curto: TAL-ist, sem acento no final.", ["tallest", "She is the tallest girl here."]], ["Everest is the ___ mountain in the world.", "tallest", "most tall", "O Everest é a montanha mais alta do mundo.", "Adjetivo curto forma o superlativo com the + -est."]];
patterns[22]=new RegExp("\\bthe \\w+est\\b","i");
themes[22]="park";
photos[22]=["photo-lake-1.webp", "photo-coast-1.webp"];
