content[23]=[[["Ben and Lou are at the cinema.", "Ben e Lou estão no cinema."], ["There are three films tonight, and Lou wants to choose.", "Há três filmes hoje à noite, e Lou quer escolher."], ["The space film is the most popular one.", "O filme sobre o espaço é o mais popular."], ["The old war drama is the most boring, says Ben.", "O velho drama de guerra é o mais chato, diz Ben."], ["They buy tickets for the film with the best scenes.", "Eles compram ingressos para o filme com as melhores cenas."]], [["Which film is the most popular tonight?", "Qual filme é o mais popular hoje à noite?"], ["The space film. Everyone says it is the best.", "O filme do espaço. Todo mundo diz que é o melhor."], ["Is it also the most interesting one?", "Ele também é o mais interessante?"], ["I think so. The scenes are very exciting.", "Acho que sim. As cenas são muito emocionantes."], ["What about the war drama at seven?", "E o drama de guerra das sete?"], ["My sister says it is the most boring film.", "Minha irmã diz que é o filme mais chato."], ["Then let us watch the space film.", "Então vamos assistir ao filme do espaço."], ["Good idea. I will buy the popcorn.", "Boa ideia. Eu compro a pipoca."]], ["Acento em interesting", "Fale IN-tres-ting, com três sílabas: o meio quase desaparece.", ["interesting", "This is an interesting book."]], ["It is the ___ film of the year.", "most interesting", "interestingest", "É o filme mais interessante do ano.", "Adjetivo longo forma o superlativo com the most."]];
patterns[23]=new RegExp("\\bthe most \\w+\\b","i");
themes[23]="ticket";
