content[24]=[[["June is comparing two phones at a small shop.", "June está comparando dois celulares em uma loja pequena."], ["The new phone has a digital screen as big as a book.", "O celular novo tem uma tela digital tão grande quanto um livro."], ["The old phone is not as heavy as the new one.", "O celular velho não é tão pesado quanto o novo."], ["Its audio is as good as the new one.", "O áudio dele é tão bom quanto o do novo."], ["The old phone is not as expensive, so June takes it.", "O celular velho não é tão caro, então June o leva."]], [["Is the old phone as fast as the new one?", "O celular velho é tão rápido quanto o novo?"], ["Not really, but the technology is almost as good.", "Não muito, mas a tecnologia é quase tão boa."], ["And the audio? Is it as good?", "E o áudio? É tão bom?"], ["Yes, it is as loud as the new one.", "Sim, é tão alto quanto o novo."], ["Is it as heavy as the other phone?", "É tão pesado quanto o outro celular?"], ["No, it is not as heavy. It is lighter.", "Não, não é tão pesado. É mais leve."], ["What is the price of the old phone?", "Qual é o preço do celular velho?"], ["It costs eighty dollars, not as much as the new one.", "Custa oitenta dólares, não tanto quanto o novo."]], ["Ligando as as", "Em as good as, o primeiro as é fraco e o segundo também: az-GUD-az.", ["as", "She is as tall as me."]], ["The old phone is not ___ heavy as the new one.", "as", "more", "O celular velho não é tão pesado quanto o novo.", "A comparação de igualdade usa as … as."]];
