plans[25]={"title": "Qual hotel é melhor", "file": "photo-luggage-1.webp", "grammar": "Comparativos irregulares: better, worse, further", "goal": "Use better, worse e further sem -er nem more, pois são formas especiais.", "words": [["worse", "pior"], ["further", "mais longe"], ["closer", "mais perto"], ["reserve", "reservar"]]};
content[25]=[[["Peg and Nico are choosing a hotel for the weekend.", "Peg e Nico estão escolhendo um hotel para o fim de semana."], ["The first hotel is better than the second one.", "O primeiro hotel é melhor que o segundo."], ["The second hotel has worse rooms and a worse breakfast.", "O segundo hotel tem quartos piores e um café da manhã pior."], ["But it is closer to the station and further from the beach.", "Mas fica mais perto da estação e mais longe da praia."], ["They book the better hotel for two nights.", "Eles reservam o melhor hotel por duas noites."]], [["Is this hotel better than the other one?", "Este hotel é melhor que o outro?"], ["Yes, the rooms are much better.", "Sim, os quartos são muito melhores."], ["What about the food? Is it worse?", "E a comida? É pior?"], ["No, it is better, and the coffee is great.", "Não, é melhor, e o café é ótimo."], ["Is the beach further from the second hotel?", "A praia fica mais longe do segundo hotel?"], ["Yes, it is about two miles further.", "Sim, fica uns três quilômetros mais longe."], ["Then we should take the first hotel.", "Então devemos ficar com o primeiro hotel."], ["Good. I will reserve two rooms right now.", "Ótimo. Vou reservar dois quartos agora mesmo."]], ["O som /ɛ/ em better", "Abra a boca um pouco, como no e de é em português; o t soa como um d rápido.", ["better", "This is a better plan."]], ["The first hotel is ___ than the second one.", "better", "gooder", "O primeiro hotel é melhor que o segundo.", "Good tem comparativo irregular: better."]];
