content[26]=[[["Lia needs a backpack for her school trip.", "Lia precisa de uma mochila para a viagem da escola."], ["The green backpack is lighter, but the blue one is stronger.", "A mochila verde é mais leve, mas a azul é mais forte."], ["The blue one has a bigger price, but it has a discount.", "A azul tem um preço maior, mas tem desconto."], ["Lia asks which one is more useful for heavy stuff.", "Lia pergunta qual é mais útil para coisas pesadas."], ["She chooses the blue backpack and pays at the counter.", "Ela escolhe a mochila azul e paga no balcão."]], [["Which backpack is better for a school trip?", "Qual mochila é melhor para uma viagem da escola?"], ["The blue one is stronger and carries more weight.", "A azul é mais forte e aguenta mais peso."], ["And the green one? Is it cheaper?", "E a verde? É mais barata?"], ["Yes, but the blue one has a discount today.", "Sim, mas a azul tem desconto hoje."], ["What is the price after the discount?", "Qual é o preço depois do desconto?"], ["It is thirty dollars, ten less than before.", "São trinta dólares, dez a menos que antes."], ["Then the blue one is the better choice.", "Então a azul é a melhor escolha."], ["I agree. You must choose one today.", "Concordo. Você precisa escolher uma hoje."]], ["O som /tʃ/ em choose", "Comece com o t e solte como em tchau: tchuz.", ["choose", "Please choose a bag."]], ["Which backpack is ___, the blue one or the green one?", "better", "more good", "Qual mochila é melhor, a azul ou a verde?", "Good vira better na comparação, nunca more good."]];
patterns[26]=new RegExp("\\b(?:better|stronger|cheaper|lighter|bigger)\\b","i");
