content[27]=[[["Ravi lives in a big city, and Ben lives in a village.", "Ravi mora em uma cidade grande, e Ben mora em um vilarejo."], ["The city is noisier and more crowded than the village.", "A cidade é mais barulhenta e mais lotada que o vilarejo."], ["The parking is terrible in the morning.", "O estacionamento é terrível de manhã."], ["Ben’s village is quieter, but the shops are fewer.", "O vilarejo de Ben é mais silencioso, mas tem menos lojas."], ["Ravi visits Ben to get some quiet.", "Ravi visita Ben para ter um pouco de silêncio."]], [["Is your city more crowded than my village?", "Sua cidade é mais lotada que o meu vilarejo?"], ["Yes, it is much noisier, too.", "Sim, é muito mais barulhenta também."], ["How is the parking in the morning?", "Como é o estacionamento de manhã?"], ["Terrible. The avenues are the most crowded.", "Terrível. As avenidas são as mais lotadas."], ["Here it is quieter, but there is less to do.", "Aqui é mais silencioso, mas há menos o que fazer."], ["I like quiet places more than busy ones.", "Eu gosto mais de lugares silenciosos que movimentados."], ["Then come to the village next weekend.", "Então venha ao vilarejo no próximo fim de semana."], ["Thanks. I will take the early train.", "Obrigado. Vou pegar o trem da manhã."]], ["O som /ɔɪ/ em noisy", "Comece com o de óleo e termine com i: NÓI-zi.", ["noisy", "The street is very noisy."]], ["The city is ___ than the village.", "more crowded", "crowdeder", "A cidade é mais lotada que o vilarejo.", "Crowded é um adjetivo longo para comparar: more crowded."]];
