content[34]=[[["Lia is at school, and bugs keep flying into the room.", "Lia está na escola, e insetos não param de entrar na sala."], ["She asks the teacher, “May I close the window?”", "Ela pergunta à professora: “Posso fechar a janela?”"], ["The teacher gives her permission to close it.", "A professora dá permissão para ela fechá-la."], ["Later, Lia needs to leave early for a doctor visit.", "Mais tarde, Lia precisa sair cedo para ir ao médico."], ["Is it OK if she leaves at three?", "Tudo bem se ela sair às três?"]], [["May I close the window, please?", "Posso fechar a janela, por favor?"], ["Yes, you may. The bugs are everywhere today.", "Pode, sim. Tem insetos por toda parte hoje."], ["Is it OK if I leave early?", "Tudo bem se eu sair mais cedo?"], ["What time do you need to leave?", "A que horas você precisa sair?"], ["At three. My hand is swollen from a bite.", "Às três. Minha mão está inchada por causa de uma picada."], ["That is fine. Do you have permission from home?", "Tudo bem. Você tem permissão de casa?"], ["Yes, my mother sent a note.", "Sim, minha mãe mandou um bilhete."], ["Good. May I see it, please?", "Ótimo. Posso ver, por favor?"]], ["O som /eɪ/ em may", "Comece em é e termine em i: mêi, com a boca abrindo pouco.", ["may", "May I come in?"]], ["___ I close the window?", "May", "Do", "Posso fechar a janela?", "May I é o pedido educado de permissão."]];
