content[35]=[[["Ava and Ravi plan a picnic for Saturday.", "Ava e Ravi planejam um piquenique para sábado."], ["There is mist over the lake this morning.", "Há névoa sobre o lago nesta manhã."], ["It might rain in the afternoon, says Ravi.", "Pode chover à tarde, diz Ravi."], ["A storm may come from the north tonight.", "Uma tempestade pode vir do norte esta noite."], ["They might have the picnic at home instead.", "Eles podem fazer o piquenique em casa."]], [["Is the picnic still on for Saturday?", "O piquenique continua de pé para sábado?"], ["I do not know. It might rain.", "Não sei. Pode chover."], ["There is mist now, but it may clear up.", "Há névoa agora, mas pode abrir o tempo."], ["What about the storm on the news?", "E a tempestade das notícias?"], ["It might arrive late on Sunday.", "Pode chegar tarde no domingo."], ["Then we might go on Saturday morning.", "Então podemos ir no sábado de manhã."], ["Good idea. I may bring sandwiches.", "Boa ideia. Posso levar sanduíches."], ["And I might bring a big blanket.", "E eu posso levar um cobertor grande."]], ["O som /aɪ/ em might", "Diga mái, com o gh mudo, e solte o t bem leve.", ["might", "It might snow."]], ["It ___ rain this afternoon.", "might", "might to", "Pode chover esta tarde.", "Might vem direto antes do verbo, sem to."]];
