content[36]=[[["Tina goes to the bank to ask for a small loan.", "Tina vai ao banco pedir um pequeno empréstimo."], ["She needs to fill out a form and show her passport.", "Ela precisa preencher um formulário e mostrar o passaporte."], ["She doesn’t need to sign the second page.", "Ela não precisa assinar a segunda página."], ["The clerk says she needs to keep the receipt.", "O atendente diz que ela precisa guardar o recibo."], ["Tina doesn’t need to come back next week.", "Tina não precisa voltar na semana que vem."]], [["What do I need to bring to the bank?", "O que preciso levar ao banco?"], ["You need to bring your passport and a form.", "Você precisa levar o passaporte e um formulário."], ["Do I need to sign every page?", "Preciso assinar todas as páginas?"], ["No, you don’t need to sign the last one.", "Não, não precisa assinar a última."], ["Do I need to keep the receipt?", "Preciso guardar o recibo?"], ["Yes, you need to keep it for a month.", "Sim, precisa guardar por um mês."], ["Do I need to pay interest today?", "Preciso pagar juros hoje?"], ["No, you don’t need to pay interest until Monday.", "Não, você não precisa pagar juros até segunda."]], ["Final -ds em needs", "Em needs, o s final soa como z: NIDZ.", ["needs", "She needs help."]], ["She ___ fill out a form.", "needs to", "need to", "Ela precisa preencher um formulário.", "Com she, use needs to."]];
patterns[36]=new RegExp("\\bneeds? to\\b|\\bdon\u2019t need to\\b|\\bdoesn\u2019t need to\\b","i");
