content[44]=[[["Lou is moving to a new apartment today.", "Lou está se mudando para um apartamento novo hoje."], ["June comes to help, but the boxes are heavy.", "A June vem ajudar, mas as caixas são pesadas."], ["“Shall I carry the big box?” she asks.", "“Devo carregar a caixa grande?”, ela pergunta."], ["Lou says, “Will you do me a favor, too?”", "Lou diz: “Você me faz um favor também?”"], ["“Will you find a cart for the other boxes?”", "“Você pode achar um carrinho para as outras caixas?”"]], [["Will you do me a favor, please?", "Você pode me fazer um favor, por favor?"], ["Sure. How can I help you?", "Claro. Como posso ajudar?"], ["Will you lift this bag into the car?", "Você pode colocar esta bolsa no carro?"], ["Of course. Shall I take the other one too?", "Claro. Devo levar a outra também?"], ["No, thanks. That one is not heavy.", "Não, obrigado. Aquela não é pesada."], ["Shall I open the door for you?", "Devo abrir a porta para você?"], ["Yes, please. And will you wait for me outside?", "Sim, por favor. E você espera por mim lá fora?"], ["Sure. I can take it to the building door.", "Claro. Posso levá-la até a porta do prédio."]], ["Entonação de pedido", "Em Will you…? a voz sobe no final, como em uma pergunta de sim ou não.", ["favor", "Will you do me a favor?"]], ["___ you lift this bag, please?", "Will", "Shall", "Você pode levantar esta bolsa, por favor?", "Para pedir algo a outra pessoa use Will you…?; Shall I…? serve para oferecer ajuda."]];
patterns[44]=new RegExp("\\b(?:will you|shall I)\\b","i");
themes[44]="chat";
