content[45]=[[["Peg and June are planning their vacation.", "Peg e June estão planejando as férias."], ["The music festival starts in a week.", "O festival de música começa em uma semana."], ["Tomorrow they are going to buy the tickets.", "Amanhã elas vão comprar os ingressos."], ["Next month, they will go skiing in the mountains.", "No mês que vem, elas vão esquiar nas montanhas."], ["They will send photos to their friends soon.", "Elas vão mandar fotos para os amigos em breve."]], [["When does your vacation start?", "Quando suas férias começam?"], ["It starts next month, on the tenth.", "Começam no mês que vem, no dia dez."], ["Nice. Are you going to the festival too?", "Legal. Você vai ao festival também?"], ["Yes, it begins in a week.", "Sim, ele começa em uma semana."], ["Did you buy the tickets already?", "Você já comprou os ingressos?"], ["No, I will buy them tomorrow morning.", "Não, vou comprá-los amanhã de manhã."], ["Will you send me a message soon?", "Você me manda uma mensagem em breve?"], ["Yes, I will write to you tomorrow night.", "Sim, escrevo para você amanhã à noite."]], ["Acento em vacation", "Acentue a segunda sílaba: vaCAtion. O a final soa como ei.", ["vacation", "Our vacation starts next month."]], ["I am going to the doctor ___ week.", "next", "last", "Vou ao médico na semana que vem.", "Next week indica o futuro; last week é passado."]];
