plans[46]={"title": "Provavelmente vai ser um bom dia", "file": "photo-street-1.webp", "grammar": "Will probably / will definitely e advérbios de certeza", "goal": "Use will probably e will definitely para mostrar o quanto você tem certeza sobre o futuro.", "words": [["definitely", "com certeza"], ["degrees", "graus"], ["swimmers", "nadadores"], ["surfing", "surfe"]]};
content[46]=[[["Ben checks the forecast on his phone.", "O Ben olha a previsão do tempo no celular."], ["It will probably be eighty degrees all afternoon.", "Provavelmente vai fazer uns trinta graus a tarde toda."], ["He will definitely wear his new sunglasses.", "Ele com certeza vai usar os óculos de sol novos."], ["His sister will probably stay home and read.", "A irmã dele provavelmente vai ficar em casa lendo."], ["They will definitely meet at the beach tonight.", "Eles com certeza vão se encontrar na praia hoje à noite."]], [["What does the forecast say today?", "O que a previsão diz para hoje?"], ["It will probably be sunny and warm.", "Provavelmente vai ficar ensolarado e quente."], ["Then I will definitely go for a run.", "Então eu com certeza vou correr."], ["Will your brother come with you?", "Seu irmão vai com você?"], ["He probably won’t. He has a lot of homework.", "Provavelmente não. Ele tem muita lição de casa."], ["Will it be cold in the evening?", "Vai fazer frio à noite?"], ["Probably a little, so I will bring a jacket.", "Um pouco, provavelmente, então vou levar um casaco."], ["Good. I will definitely call you later.", "Bom. Com certeza ligo para você mais tarde."]], ["Palavra probably", "Muita gente fala “PRÓbli”. Diga PRÓ-bli, com três sons só, sem o a no meio.", ["probably", "It will probably rain."]], ["It ___ be sunny tomorrow.", "will probably", "probably will to", "Provavelmente vai ficar ensolarado amanhã.", "Probably vem depois de will e antes do verbo base."]];
