plans[48]={"title": "O que você vai fazer no fim de semana", "file": "photo-square-1.webp", "grammar": "What are you going to do? e perguntas sobre planos", "goal": "Use What are you going to do…?, Where…? e Who…? com be going to para perguntar sobre os planos de alguém.", "words": [["relax", "relaxar"], ["guess", "acho que"], ["mosque", "mesquita"], ["easter", "Páscoa"]]};
content[48]=[[["It is Friday, and Lia asks about the weekend.", "É sexta-feira, e a Lia pergunta sobre o fim de semana."], ["Her cousin is a visitor from another city.", "O primo dela é um visitante de outra cidade."], ["They are going to relax and walk around the old square.", "Eles vão relaxar e passear pela praça antiga."], ["Lia is not going to sleep late on Sunday.", "A Lia não vai dormir até tarde no domingo."], ["She has a lot of plans for the weekend.", "Ela tem muitos planos para o fim de semana."]], [["What are you going to do this weekend?", "O que você vai fazer neste fim de semana?"], ["My cousin is going to visit me.", "Meu primo vai me visitar."], ["Nice! Where are you going to take him?", "Legal! Aonde você vai levá-lo?"], ["We are going to see the old square.", "Vamos ver a praça antiga."], ["Who else is going to come with you?", "Quem mais vai com você?"], ["Two friends from work are going to join us.", "Dois amigos do trabalho vão se juntar a nós."], ["Are you going to sleep late on Sunday?", "Você vai dormir até tarde no domingo?"], ["I guess not. I have a lot of plans.", "Acho que não. Tenho muitos planos."]], ["Reduzindo going to", "Na fala rápida, going to vira “gonna”. Entenda, mas escreva going to.", ["going to", "What are you going to do?"]], ["What ___ you going to do on Sunday?", "are", "do", "O que você vai fazer no domingo?", "A pergunta com be going to começa com am/is/are antes do sujeito."]];
