content[49]=[[["Lia is moving to a new city next month.", "A Lia vai se mudar para uma cidade nova no mês que vem."], ["Her apartment is on the fifth floor, with an elevator.", "O apartamento dela fica no quinto andar, com elevador."], ["Ravi is going to drive the moving truck.", "O Ravi vai dirigir o caminhão de mudança."], ["He will probably arrive at her new address by noon.", "Ele provavelmente vai chegar ao novo endereço dela ao meio-dia."], ["Lia might hire a cleaner for the old flat, but she is not sure.", "Lia talvez contrate uma faxineira para o apartamento antigo, mas não tem certeza."]], [["Where are you going to live in the new city?", "Onde você vai morar na cidade nova?"], ["I am going to rent an apartment near the park.", "Vou alugar um apartamento perto do parque."], ["Will you send me your new address soon?", "Você me manda seu novo endereço em breve?"], ["Yes, I will write it down tomorrow.", "Sim, vou anotá-lo amanhã."], ["Is there an elevator in the building?", "Tem elevador no prédio?"], ["Yes, there is, so the boxes won’t be a problem.", "Tem, então as caixas não vão ser problema."], ["When is the moving truck going to arrive?", "Quando o caminhão de mudança vai chegar?"], ["It will definitely arrive on Saturday morning.", "Com certeza chega no sábado de manhã."]], ["Acento em apartment", "Acentue a segunda sílaba: aPARTment. O a inicial é fraco, quase um é.", ["apartment", "My apartment is on the second floor."]], ["The truck ___ arrive on Saturday morning.", "is going to", "going to", "O caminhão vai chegar no sábado de manhã.", "Be going to precisa de am/is/are antes."]];
patterns[49]=new RegExp("\\b(?:is|am|are) (?:not )?going to\\b|\\bwill\\b","i");
themes[49]="city";
photos[49]=["photo-luggage-1.webp", "photo-ticketdesk-1.webp"];
stories[49]=["Lia muda de cidade", "Lia is going to move to a new city next month.~Lia vai se mudar para uma cidade nova no mês que vem.|She has a small apartment waiting near a quiet park.~Ela tem um apartamento pequeno esperando perto de um parque tranquilo.|Ravi promises he will help her with all the boxes.~Ravi promete que vai ajudá-la com todas as caixas.|On Saturday morning, the moving truck is not at the door.~No sábado de manhã, o caminhão de mudança não está na porta.|Lia is worried, and she calls Ravi on her phone.~Lia fica preocupada e liga para o Ravi no celular.|He says the truck will probably arrive in an hour.~Ele diz que o caminhão provavelmente chega em uma hora.|It is going to rain, so they cover the boxes.~Vai chover, então eles cobrem as caixas.|Finally, the truck arrives, and the elevator works well.~Por fim, o caminhão chega, e o elevador funciona bem.|By night, Lia is going to sleep in her new bed.~À noite, a Lia vai dormir na cama nova.|Tomorrow she will send her new address to everyone.~Amanhã ela vai mandar o novo endereço para todos."];
