content[50]=[[["Ben has visited a castle in the north.", "O Ben já visitou um castelo no norte."], ["He has also raced his cousin on the beach.", "Ele também já apostou corrida com o primo na praia."], ["His friend Ava has met a monk on a trip.", "A amiga dele, Ava, já conheceu um monge em uma viagem."], ["They have played in a brass band at school.", "Eles já tocaram em uma banda de metais na escola."], ["Now they have many stories to tell.", "Agora eles têm muitas histórias para contar."]], [["Where have you traveled in your life?", "Onde você já viajou na vida?"], ["I have visited a castle in Scotland.", "Eu já visitei um castelo na Escócia."], ["Wow! Have you seen a monk there?", "Uau! Você já viu um monge lá?"], ["Yes, I have talked to one for an hour.", "Já, conversei com um por uma hora."], ["My sister has played in a brass band, but I have not.", "Minha irmã já tocou em uma banda de metais, mas eu não."], ["Then we have to hear her next concert.", "Então temos que ouvir o próximo show dela."], ["Has your brother thrown a disc yet?", "Seu irmão já lançou um disco (frisbee)?"], ["He has, and he is really good now.", "Já, e agora ele é muito bom."]], ["Som de h em has e have", "O h é soprado, com o ar saindo da garganta; não é o r do português.", ["have", "I have a big family."]], ["I ___ a castle in Scotland.", "have visited", "visit have", "Eu já visitei um castelo na Escócia.", "A experiência usa have + particípio passado (visited)."]];
