content[51]=[[["Peg has never felt an earthquake.", "Peg nunca sentiu um terremoto."], ["Her uncle has felt one in Chile.", "O tio dela já sentiu um no Chile."], ["Noah has never touched a rat at a pet shop.", "Noah nunca tocou em um rato em uma loja de animais."], ["Peg has seen a beaver once, as a child.", "Peg já viu um castor uma vez, quando criança."], ["Neither of them has ever jumped with a parachute.", "Nenhum dos dois jamais pulou de paraquedas."]], [["Have you ever felt an earthquake?", "Você já sentiu um terremoto?"], ["No, I have never seen one. Have you?", "Não, nunca vi um. E você?"], ["My uncle has, but I have not.", "Meu tio já viu, mas eu não."], ["Have you ever touched a rat?", "Você já tocou em um rato?"], ["Never! I am afraid of rats.", "Nunca! Tenho medo de ratos."], ["Have you ever seen a beaver?", "Você já viu um castor?"], ["Yes, once. It was building a small dam.", "Já, uma vez. Ele estava construindo uma represinha."], ["I have never used a parachute, but I would like to.", "Nunca usei paraquedas, mas gostaria."]], ["Entonação em Have you ever…?", "A voz sobe no final. Ever soa como “ÉV-er”, com o v bem marcado.", ["ever", "Have you ever seen snow?"]], ["Have you ___ felt an earthquake?", "ever", "never", "Você já sentiu um terremoto alguma vez?", "Em perguntas de experiência, usamos ever."]];
