content[52]=[[["Ava’s parents are coming for dinner at seven.", "Os pais da Ava vêm jantar às sete."], ["She has already washed the shirts.", "Ela já lavou as camisas."], ["She has already cleaned the bathroom.", "Ela já limpou o banheiro."], ["But she has not cleaned the living room yet.", "Mas ela ainda não limpou a sala."], ["Nico has not finished the cake yet either.", "O Nico também ainda não terminou o bolo."]], [["Have you cleaned the house yet?", "Você já limpou a casa?"], ["I have already washed the shirts.", "Eu já lavei as camisas."], ["Good. Have you cleaned the bathroom yet?", "Ótimo. Você já limpou o banheiro?"], ["Yes, I have already done that too.", "Sim, também já fiz isso."], ["What about the living room floor?", "E o chão da sala?"], ["I have not started to clean it yet.", "Eu ainda não comecei a limpar."], ["Hurry up! Have you ironed the shirts?", "Anda logo! Você já passou as camisas?"], ["Do not worry. It will take ten minutes.", "Não se preocupe. Vai levar dez minutos."]], ["Palavra already", "Acentue a segunda sílaba: alREdy. O r é suave, como em hora.", ["already", "I have already eaten."]], ["I have ___ cleaned the kitchen.", "already", "yet", "Eu já limpei a cozinha.", "Already vai em frases afirmativas; yet vai em perguntas e negativas."]];
