content[54]=[[["Ravi has liked music by one composer for six years.", "O Ravi gosta da música de um compositor há seis anos."], ["He has played in the school orchestra since September.", "Ele toca na orquestra da escola desde setembro."], ["The teacher has known his family since he was little.", "O professor conhece a família dele desde que ele era pequeno."], ["Ava has listened to their practice for two weeks.", "A Ava ouve o ensaio deles há duas semanas."], ["They have practiced in the same room since last spring.", "Eles ensaiam na mesma sala desde a primavera passada."]], [["How long have you liked that composer?", "Há quanto tempo você gosta desse compositor?"], ["I have liked him for six years.", "Gosto dele há seis anos."], ["Are you in the school orchestra now?", "Você está na orquestra da escola agora?"], ["Yes, I have played there since September.", "Sim, toco lá desde setembro."], ["Has your teacher helped you for a long time?", "Seu professor ajuda você há muito tempo?"], ["He has helped me since I was twelve.", "Ele me ajuda desde que eu tinha doze anos."], ["Do you practice after dinner every day?", "Você pratica depois do jantar todos os dias?"], ["Yes, I have practiced for an hour today.", "Sim, hoje pratiquei por uma hora."]], ["Acento em orchestra", "A sílaba forte é a primeira: ÓR-kes-tra. O ch soa como k.", ["orchestra", "I play in the orchestra."]], ["I have lived here ___ 2020.", "since", "for", "Moro aqui desde 2020.", "Since vem com um ponto no tempo (2020); for vem com um período."]];
patterns[54]=new RegExp("\\b(?:for|since) \\w+","i");
themes[54]="notebook";
photos[54]=["photo-note-1.webp", "photo-study-1.webp"];
plans[55]={"title": "Já estive lá ou foi embora?", "file": "photo-coast-1.webp", "grammar": "Been e gone: Have you ever been to…?", "goal": "Use been to para dizer que alguém foi e voltou, e gone to para dizer que a pessoa foi e ainda está lá.", "words": [["canal", "canal"], ["cruise", "cruzeiro"], ["temple", "templo"], ["jungle", "selva"]]};
content[55]=[[["Tina is not here. She has gone to the canal.", "A Tina não está aqui. Ela foi até o canal."], ["Ben has been on a cruise twice with his family.", "O Ben já fez dois cruzeiros com a família."], ["He has never been to the old temple in town.", "Ele nunca foi ao templo antigo da cidade."], ["Ava has gone to the temple to take photos.", "A Ava foi ao templo tirar fotos."], ["She will be back soon, so please wait for her.", "Ela volta logo, então espere por ela, por favor."]], [["Have you ever been on a cruise?", "Você já fez um cruzeiro?"], ["Yes, I have been on one with my parents.", "Sim, fiz um com meus pais."], ["Where has your sister gone today?", "Aonde sua irmã foi hoje?"], ["She has gone to the canal with Ben.", "Ela foi ao canal com o Ben."], ["Have you ever been to the temple?", "Você já esteve no templo?"], ["No, I have never been there.", "Não, nunca estive lá."], ["Would you like to go with us?", "Quer ir com a gente?"], ["Yes, I would love to. Let us go now.", "Quero sim. Vamos agora."]], ["Been com som de bin", "Nos Estados Unidos, been costuma soar como “bin”, com i curto.", ["been", "I have been to Rio."]], ["Tina is not here. She has ___ to the temple.", "gone", "been", "A Tina não está aqui. Ela foi ao templo.", "Gone to significa que a pessoa foi e ainda não voltou; been to é para quem já voltou."]];
patterns[55]=new RegExp("\\b(?:been|gone) to\\b","i");
themes[55]="map";
