plans[56]={"title": "Presente perfeito ou passado simples", "file": "photo-stationSign-1.webp", "grammar": "Presente perfeito ou passado simples? (a data muda tudo)", "goal": "Use o presente perfeito sem dizer quando; com uma data ou hora passada (last year, in 2019) use o passado simples.", "words": [["musician", "músico"], ["stadium", "estádio"], ["comedian", "comediante"], ["tournament", "torneio"]]};
content[56]=[[["Ben has seen a famous musician in concert.", "O Ben já viu uma musicista famosa em um show."], ["He saw her last year at a big stadium.", "Ele a viu no ano passado em um estádio grande."], ["Ben has also watched a soccer tournament there this spring.", "O Ben também assistiu a um torneio de futebol lá nesta primavera."], ["Ava has never been to a stadium show.", "A Ava nunca foi a um show em estádio."], ["She wanted to go in 2022, but she was sick.", "Ela queria ir em 2022, mas estava doente."]], [["Have you ever seen a musician in concert?", "Você já viu um músico em um show?"], ["Yes, I saw one last year.", "Sim, vi um no ano passado."], ["Where did you see the musician?", "Onde você viu o músico?"], ["At the stadium near the river.", "No estádio perto do rio."], ["Did anyone else perform that night?", "Mais alguém se apresentou naquela noite?"], ["Yes, a comedian made everyone laugh first.", "Sim, um comediante fez todo mundo rir primeiro."], ["I have never been to a stadium show.", "Eu nunca fui a um show em estádio."], ["You should go next time. It was amazing.", "Você devia ir da próxima vez. Foi incrível."]], ["Passado de saw e see", "Saw soa como “só”, com o som aberto. Não confunda com see (si).", ["saw", "I saw a musician last year."]], ["I ___ a musician last year.", "saw", "have seen", "Eu vi um músico no ano passado.", "Com last year, que marca um tempo passado, use o passado simples."]];
patterns[56]=new RegExp("\\b(?:have|has) (?:never )?(?:seen|been)\\b|\\b(?:saw|sang|was|wanted) [a-z ]*(?:last year|2022)?","i");
themes[56]="ticket";
photos[56]=["photo-ticketdesk-2.webp", "photo-restaurant-2.webp"];
