content[57]=[[["Tina has a set of silver spoons from her grandmother.", "A Tina tem um jogo de colheres de prata da avó."], ["She has had them for ten years.", "Ela as tem há dez anos."], ["Lou has lost a small jewel, and he has looked everywhere.", "O Lou perdeu uma joia pequena e procurou por toda parte."], ["He has had that jewel since his birthday.", "Ele tem essa joia desde o aniversário."], ["Tina and Lou have used the same tool kit since 2020.", "A Tina e o Lou usam o mesmo kit de ferramentas desde 2020."]], [["Are those new spoons on the table?", "Aquelas colheres na mesa são novas?"], ["No, I have had them for ten years.", "Não, eu as tenho há dez anos."], ["Who gave them to you?", "Quem deu a você?"], ["My grandmother did. She also gave me this handkerchief.", "Minha avó. Ela também me deu este lenço."], ["How long have you known Lou?", "Há quanto tempo você conhece o Lou?"], ["We have known each other since school.", "Nos conhecemos desde a escola."], ["Does Lou still use that tool kit?", "O Lou ainda usa aquele kit de ferramentas?"], ["Yes, we have used it since last year.", "Sim, usamos desde o ano passado."]], ["Entonação em How long", "A voz cai no final da pergunta com palavra de pergunta. Long soa como “lóng”.", ["long", "How long have you lived here?"]], ["How long ___ you had those spoons?", "have", "do", "Há quanto tempo você tem essas colheres?", "How long + have + particípio pergunta a duração de um estado que ainda continua."]];
patterns[57]=new RegExp("\\bhow long (?:have|has)\\b|\\b(?:have|has) had\\b|\\b(?:have|has) known\\b","i");
