content[58]=[[["Noah has written an essay about the sea today.", "O Noah escreveu hoje uma redação sobre o mar."], ["He has also done all of his homework.", "Ele também fez toda a lição de casa."], ["Peg has eaten peanut butter every morning this week.", "A Peg comeu pasta de amendoim toda manhã esta semana."], ["She has seen a dolphin on a boat trip.", "Ela já viu um golfinho em um passeio de barco."], ["Now she has read half of a book about the ocean.", "Agora ela já leu metade de um livro sobre o oceano."]], [["What have you done this morning?", "O que você fez esta manhã?"], ["I have written an essay for class.", "Escrevi uma redação para a aula."], ["Who will read it? Have you finished?", "Quem vai ler? Você já terminou?"], ["My teacher will read it. Not yet.", "Meu professor vai ler. Ainda não."], ["Have you eaten anything today?", "Você já comeu alguma coisa hoje?"], ["Yes, I have eaten liver for lunch.", "Sim, comi fígado no almoço."], ["Have you ever seen a dolphin?", "Você já viu um golfinho?"], ["Yes, I have, and I loved it.", "Já, e adorei."]], ["Particípio eaten", "Diga “ÍTen”, com o t suave e a vogal curta no final. Não é “eiten”.", ["eaten", "I have eaten pasta."]], ["She has ___ a letter to her mother.", "written", "wrote", "Ela escreveu uma carta para a mãe.", "Com has, use o particípio written; wrote é o passado simples."]];
