plans[59]={"title": "Dia de carreira na escola", "file": "photo-desk-1.webp", "grammar": "Revisão: presente perfeito, ever/never, already/yet, just, for/since", "goal": "Revise o presente perfeito numa entrevista de emprego, com experiências, ever, never, just, for e since.", "words": [["architect", "arquiteto"], ["astronaut", "astronauta"], ["accountant", "contador"], ["agent", "agente"]]};
content[59]=[[["It is career day, and Ava has met an astronaut.", "É o dia da carreira, e a Ava conheceu um astronauta."], ["He has flown in space twice and has seen the Earth.", "Ele voou duas vezes ao espaço e viu a Terra de lá."], ["An architect has designed many houses in our city.", "Uma arquiteta projetou muitas casas na nossa cidade."], ["The accountant has worked with numbers for ten years.", "O contador trabalha com números há dez anos."], ["A travel agent has booked trips for many years.", "Uma agente de viagens reserva viagens há muitos anos."]], [["Have you ever met a real astronaut?", "Você já conheceu um astronauta de verdade?"], ["Yes, I have met one today at school.", "Sim, conheci um hoje na escola."], ["What has he done in his life?", "O que ele fez na vida?"], ["He has flown in space twice.", "Ele já voou ao espaço duas vezes."], ["Have you talked with the architect yet?", "Você já conversou com a arquiteta?"], ["No, I have not, but I have seen her houses.", "Ainda não, mas já vi as casas dela."], ["Have you ever wanted to be an accountant?", "Você já quis ser contador?"], ["No, I have never liked numbers very much.", "Não, nunca gostei muito de números."]], ["Acento em astronaut e architect", "Em astronaut a sílaba forte é a primeira: ÁS-tro-nót. Em architect também: AR-ki-tekt.", ["astronaut", "The astronaut has flown twice."]], ["I have worked here ___ two years.", "for", "since", "Trabalho aqui há dois anos.", "For vem com um período de tempo (two years)."]];
patterns[59]=new RegExp("\\b(?:have|has) (?:never |just |already |not )?\\w+\\b","i");
themes[59]="chat";
photos[59]=["photo-desk-1.webp", "photo-deskStudy-1.webp"];
stories[59]=["O dia de carreira do Ravi", "Ravi has played in the school orchestra since September.~O Ravi toca na orquestra da escola desde setembro.|Today is career day, and he has never felt so nervous.~Hoje é o dia da carreira, e ele nunca se sentiu tão nervoso.|He has met an astronaut, an architect, and an accountant already.~Ele já conheceu um astronauta, uma arquiteta e um contador.|The astronaut has flown in space twice and loves music.~O astronauta já voou ao espaço duas vezes e adora música.|She asks Ravi how long he has liked music.~Ela pergunta ao Ravi há quanto tempo ele gosta de música.|He has liked it for six years, and she smiles.~Ele gosta há seis anos, e ela sorri.|The accountant has never played an instrument, but he listens daily.~O contador nunca tocou um instrumento, mas ouve música todo dia.|Ravi has promised to play something for them after lunch.~O Ravi prometeu tocar algo para eles depois do almoço.|He plays one slow song while the astronaut hums along.~Ele toca uma música lenta enquanto a astronauta cantarola junto.|Everyone claps, and Ravi has never felt so proud.~Todos aplaudem, e o Ravi nunca se sentiu tão orgulhoso."];
