content[60]=[[["Ben has a neighbor who is a surgeon.", "O Ben tem um vizinho que é cirurgião."], ["He is the man who lives next to the park.", "Ele é o homem que mora ao lado do parque."], ["His sister is a hairdresser who works near the station.", "A irmã dele é cabeleireira e trabalha perto da estação."], ["The hunter who lives upstairs knows everyone here.", "O caçador que mora no andar de cima conhece todo mundo aqui."], ["Tonight a policeman who plays drums joins the band.", "Hoje à noite um policial que toca bateria entra na banda."]], [["Do you know the man who works at the hospital?", "Você conhece o homem que trabalha no hospital?"], ["Yes, he is the neighbor who lives in number five.", "Sim, ele é o vizinho que mora no número cinco."], ["Is he the one who has a red car?", "Ele é o que tem um carro vermelho?"], ["No, that is the woman who works at the bank.", "Não, essa é a mulher que trabalha no banco."], ["Who is the girl who sings with him?", "Quem é a moça que canta com ele?"], ["She is his sister, who is a hairdresser.", "É a irmã dele, que é cabeleireira."], ["Do you know the hunter who lives here?", "Você conhece o caçador que mora aqui?"], ["Yes, she is the girl who says hello every day.", "Sim, ela é a moça que diz oi todos os dias."]], ["O som /w/ em who e woman", "Em who, o w quase não aparece: diga /hu/. Em woman, arredonde os lábios para o /w/.", ["who", "The man who plays is my neighbor."]], ["Ben likes the neighbor ___ plays the piano.", "who", "which", "Ben gosta do vizinho que toca piano.", "Para pessoas, use who depois do substantivo."]];
