content[61]=[[["Mia loves the spaceship which she bought last week.", "A Mia adora a nave espacial que comprou semana passada."], ["The submarine, which is bright yellow, fits in the bath.", "O submarino, que é amarelo-vivo, cabe na banheira."], ["The tanker, which is very light, floats in the sink.", "O navio-tanque, que é muito leve, flutua na pia."], ["But the lorry which has the big wheels is broken.", "Mas o caminhão que tem as rodas grandes está quebrado."], ["She goes back to the shop which sells larger lorries.", "Ela volta à loja que vende caminhões maiores."]], [["Is that the spaceship which you bought online?", "Essa é a nave espacial que você comprou on-line?"], ["No, I bought it in the shop which is near the station.", "Não, comprei na loja que fica perto da estação."], ["Which toy does your nephew like best?", "De qual brinquedo seu sobrinho mais gosta?"], ["He likes the submarine which has a little light.", "Ele gosta do submarino que tem uma luzinha."], ["Is the tanker which you have easy to fill?", "O navio-tanque que você tem é fácil de encher?"], ["Yes, it is the best toy which I have ever had.", "Sim, é o melhor brinquedo que já tive."], ["Does the lorry which you have hold many boxes?", "O caminhão que você tem carrega muitas caixas?"], ["Yes, he only fills it with small cars.", "Sim, ele só enche de carrinhos pequenos."]], ["O som /w/ em which", "Arredonde os lábios como em “uau” e abra: uích. Não diga “quich”.", ["which", "The toy which I like is red."]], ["The phone ___ I bought is very fast.", "which", "who", "O celular que eu comprei é muito rápido.", "Para coisas, use which, não who."]];
