content[62]=[[["The sheriff that Peg hired came on Saturday.", "O xerife que a Peg contratou veio no sábado."], ["The tune that he played made the children laugh.", "A melodia que ele tocou fez as crianças rirem."], ["He did a trick that nobody could explain.", "Ele fez um truque que ninguém conseguiu explicar."], ["Peg found a clue that was hidden in the hat.", "A Peg achou uma pista que estava escondida no chapéu."], ["It is the best party that she has ever planned.", "É a melhor festa que ela já planejou."]], [["Is that the sheriff that you hired for the party?", "Esse é o xerife que você contratou para a festa?"], ["Yes, he is the one that came on Saturday.", "Sim, é o que veio no sábado."], ["Who is the man that taught him the trick?", "Quem é o homem que ensinou o truque a ele?"], ["He is a friend that works at the theater.", "É um amigo que trabalha no teatro."], ["What is the tune that he played?", "Qual é a melodia que ele tocou?"], ["It is a song that my grandmother loved.", "É uma canção que minha avó adorava."], ["Is there a clue that explains the trick?", "Existe alguma pista que explique o truque?"], ["Yes, the hat that he held had a small door.", "Sim, o chapéu que ele segurava tinha uma portinha."]], ["O som /ð/ em that", "Ponha a ponta da língua entre os dentes e faça vibrar a voz: /ðæt/.", ["that", "That is the package that I want."]], ["The man ___ brought the box is my neighbor.", "that", "what", "O homem que trouxe a caixa é meu vizinho.", "Depois de man ou box, use that (ou who). Não use what."]];
