content[63]=[[["Peg shows Lou the village where she grew up.", "A Peg mostra ao Lou o vilarejo onde ela cresceu."], ["This is the oak where she played every day.", "Este é o carvalho onde ela brincava todos os dias."], ["The greenhouse where her father grew flowers is still there.", "A estufa onde o pai dela cultivava flores ainda está lá."], ["Above it is the branch where her cat slept all summer.", "Acima dela fica o galho onde a gata dormia todo o verão."], ["Now it is a place where children from the street meet.", "Hoje é um lugar onde as crianças da rua se encontram."]], [["Is this the village where you were born?", "Este é o vilarejo onde você nasceu?"], ["No, I was born in a town where there is a big lake.", "Não, nasci numa cidade onde há um lago grande."], ["Is there a shop where we can buy water?", "Há uma loja onde a gente possa comprar água?"], ["Yes, there is a small one where my aunt works.", "Sim, há uma pequena onde minha tia trabalha."], ["Can you show me the stones where we can sit?", "Pode me mostrar as pedras onde podemos sentar?"], ["Of course. It is the place where the old school was.", "Claro. É o lugar onde ficava a escola antiga."], ["Is that the branch where your cat sleeps?", "Esse é o galho onde sua gata dorme?"], ["Yes, it is the only place where she feels safe.", "Sim, é o único lugar onde ela se sente segura."]], ["O som /w/ + /ɛr/ em where", "Arredonde os lábios para o /w/ e termine com um /ɛr/ aberto, sem o r forte do português.", ["where", "This is where I live."]], ["This is the garage ___ my father works.", "where", "who", "Esta é a garagem onde meu pai trabalha.", "Para lugares, use where depois do substantivo."]];
