content[64]=[[["June moves to a new flat in the city.", "A June se muda para um apartamento novo na cidade."], ["There is a lot of traffic, but not much noise inside.", "Há muito trânsito, mas não muito barulho lá dentro."], ["She has only a few valuables and plenty of space.", "Ela tem só alguns objetos de valor e bastante espaço."], ["A few friends come to help with the boxes.", "Alguns amigos vêm ajudar com as caixas."], ["There are not many chairs, so they sit on the floor.", "Não há muitas cadeiras, então eles sentam no chão."]], [["How many valuables do you have?", "Quantos objetos de valor você tem?"], ["Only a few. I have a bed and a small table.", "Só algumas. Tenho uma cama e uma mesa pequena."], ["Are there many people in your building?", "Há muita gente no seu prédio?"], ["No, only a few families live here.", "Não, só algumas famílias moram aqui."], ["Is there much traffic in this area?", "Há muito trânsito nesta região?"], ["Not much, but there is a crowd near the station.", "Não muito, mas há uma multidão perto da estação."], ["Do you have plenty of time today?", "Você tem bastante tempo hoje?"], ["Yes, I have plenty of time until six.", "Sim, tenho bastante tempo até as seis."]], ["Acento em many e much", "Em many, diga /ˈmɛni/ com o e aberto. Em much, a vogal é curta, como /mʌtʃ/.", ["many", "How many chairs are there?"]], ["There are not ___ chairs in the room.", "many", "much", "Não há muitas cadeiras no quarto.", "Chairs é contável: use many, não much."]];
