content[65]=[[["Ava takes her brother to see the ape.", "A Ava leva o irmão para ver o macaco."], ["It is too big for the small window.", "Ele é grande demais para a janela pequena."], ["The bird has one wing too weak to fly far.", "O pássaro tem uma asa fraca demais para voar longe."], ["The creature is young, but big enough to walk alone.", "A criatura é nova, mas grande o bastante para andar sozinha."], ["The flea on the dog is too small to see.", "A pulga no cachorro é pequena demais para ver."]], [["Can you see the ape from here?", "Você consegue ver o macaco daqui?"], ["No, it is too far. Let us move closer.", "Não, está longe demais. Vamos chegar mais perto."], ["Is this spot close enough for a photo?", "Este lugar é perto o bastante para uma foto?"], ["Yes, but the sun is too bright. Wait.", "É, mas o sol está forte demais. Espere."], ["Is the flea too small for your camera?", "A pulga é pequena demais para a sua câmera?"], ["Yes, but I think the photo is good enough.", "Está, mas acho que a foto está boa o bastante."], ["Is the path too long for the children?", "O caminho é longo demais para as crianças?"], ["No, they are strong enough. Let us walk.", "Não, elas são fortes o bastante. Vamos andar."]], ["Acento em enough e too", "Em enough, o gh soa como /f/: /ɪˈnʌf/. Em too, alongue o /uː/.", ["enough", "This is big enough."]], ["The ape is ___ for the small window.", "too big", "big too", "O macaco é grande demais para a janela pequena.", "Em inglês, too vem antes do adjetivo; enough vem depois dele."]];
patterns[65]=new RegExp("\\btoo \\w+|\\w+ enough\\b","i");
themes[65]="park";
photos[65]=["photo-walk-1.webp", "photo-parkPath-1.webp"];
plans[66]={"title": "A carteira que sumiu", "file": "photo-counter-2.webp", "grammar": "Pronomes indefinidos: someone, anything, nobody, everywhere", "goal": "Use someone, anything, nobody e everywhere para falar de pessoas, coisas e lugares sem dar nomes.", "words": [["keys", "chaves"], ["somewhere", "em algum lugar"], ["nobody", "ninguém"], ["pound", "libra"]]};
content[66]=[[["Noah cannot find his wallet anywhere.", "Noah não acha sua carteira em lugar nenhum."], ["He looks everywhere, but he sees nothing on the table.", "Ele procura em todo lugar, mas não vê nada na mesa."], ["Someone knocks on the door and holds up some keys.", "Alguém bate à porta e mostra algumas chaves."], ["Nobody knows whose keys they are, so Noah smiles.", "Ninguém sabe de quem são as chaves, então Noah sorri."], ["His wallet is somewhere in the car, he thinks.", "A carteira dele está em algum lugar do carro, ele acha."]], [["Is there anything in your bag?", "Tem alguma coisa na sua bolsa?"], ["No, nothing. My wallet is not here.", "Não, nada. Minha carteira não está aqui."], ["Did you look everywhere in the house?", "Você procurou em toda a casa?"], ["Yes, and nobody has seen it.", "Sim, e ninguém viu."], ["Maybe someone took it by mistake.", "Talvez alguém tenha levado por engano."], ["Is there anyone at home who can check?", "Tem alguém em casa que possa conferir?"], ["Yes, my sister is there. I will call her.", "Tem, minha irmã está lá. Vou ligar para ela."], ["Good. Tell me if she finds anything.", "Ótimo. Me avise se ela achar alguma coisa."]], ["Acento em some- e any-", "Nas palavras someone, anything e everywhere, a primeira sílaba é a mais forte.", ["someone", "Someone is at the door."]], ["I cannot find my keys ___.", "anywhere", "nowhere", "Não consigo achar minhas chaves em lugar nenhum.", "Com cannot, use anywhere; nowhere já é negativo."]];
patterns[66]=new RegExp("\\b(someone|anyone|anything|nobody|nothing|everywhere|anywhere|somewhere|everyone|something)\\b","i");
themes[66]="chat";
photos[66]=["photo-counter-2.webp", "photo-bag-1.webp"];
