plans[67]={"title": "Eu me cortei, sem querer", "file": "photo-bakery-1.webp", "grammar": "Reflexivos: myself, yourself, themselves", "goal": "Use myself, yourself, himself e themselves quando o sujeito e o objeto são a mesma pessoa.", "words": [["bruise", "hematoma"], ["burn", "queimar"], ["themselves", "si mesmos"], ["bleed", "sangrar"]]};
content[67]=[[["Tina falls on the stairs and hurts herself.", "A Tina cai na escada e se machuca."], ["She looks at herself in the mirror and laughs.", "Ela se olha no espelho e ri."], ["Her brothers burn themselves on the hot pan.", "Os irmãos dela se queimam na panela quente."], ["Tina tells them, \"Please be careful with yourselves.\"", "A Tina diz a eles: “Tomem cuidado, por favor.”"], ["They all make dinner by themselves tonight.", "Todos eles fazem o jantar sozinhos hoje."]], [["Did you hurt yourself on the stairs?", "Você se machucou na escada?"], ["Yes, I got a bruise, and my knee began to bleed.", "Sim, fiquei com um hematoma e o joelho começou a sangrar."], ["Please look at yourself in the mirror.", "Por favor, olhe-se no espelho."], ["I am fine. Look, it is only a small bruise.", "Estou bem. Olhe, é só um hematoma pequeno."], ["Do the children cook by themselves?", "As crianças cozinham sozinhas?"], ["Sometimes. They make eggs for themselves.", "Às vezes. Elas fazem ovos para si mesmas."], ["Does Ben cut his own hair?", "O Ben corta o próprio cabelo?"], ["Yes, he cuts it himself every month.", "Sim, ele mesmo corta todo mês."]], ["O som /ð/ em themselves", "Ponha a língua entre os dentes no começo: /ðəmˈsɛlvz/. Termine com o /vz/ bem suave.", ["themselves", "They help themselves."]], ["Be careful, or you will hurt ___.", "yourself", "you", "Cuidado, ou você vai se machucar.", "Quando o sujeito age sobre si mesmo, use yourself."]];
patterns[67]=new RegExp("\\b(myself|yourself|himself|herself|themselves|ourselves|yourselves)\\b","i");
themes[67]="health";
photos[67]=["photo-clinic-1.webp", "photo-bakery-1.webp"];
plans[68]={"title": "Química ou biologia?", "file": "photo-restaurant-2.webp", "grammar": "Both, either e neither em escolhas simples", "goal": "Use both para os dois, either para um dos dois e neither para nenhum dos dois.", "words": [["chemistry", "química"], ["biology", "biologia"], ["either", "um ou outro"], ["neither", "nenhum dos dois"]]};
content[68]=[[["Lou and Nico look at the school list together.", "O Lou e o Nico olham juntos a lista da escola."], ["Both like chemistry, but neither wants an early class.", "Os dois gostam de química, mas nenhum quer aula cedo."], ["Lou can take either biology or a language class.", "O Lou pode fazer biologia ou uma aula de idiomas."], ["For the lab, both choose the Tuesday group.", "Para o laboratório, os dois escolhem o grupo de terça."], ["Neither of them likes to study at night.", "Nenhum dos dois gosta de estudar à noite."]], [["Do you want chemistry or biology?", "Você quer química ou biologia?"], ["Either is fine. I like both.", "Qualquer uma serve. Gosto das duas."], ["Which group do you want, Monday or Tuesday?", "Qual grupo você quer, segunda ou terça?"], ["Neither, thanks. I am busy both days.", "Nenhum, obrigado. Estou ocupado nos dois dias."], ["Both of these teachers look nice.", "Os dois professores parecem simpáticos."], ["Then we can take either one.", "Então podemos escolher qualquer um."], ["Does either of you want to study tonight?", "Algum de vocês quer estudar hoje à noite?"], ["Both of us do. Let us start at six.", "Nós dois queremos. Vamos começar às seis."]], ["Duas formas de either e neither", "Nos Estados Unidos, either e neither começam com o som /i/: /ˈiðər/ e /ˈniðər/.", ["either", "Either is fine."]], ["I like tea and coffee. I like ___ of them.", "both", "either", "Eu gosto de chá e de café. Gosto dos dois.", "Both significa os dois juntos."]];
patterns[68]=new RegExp("\\b(both|either|neither)\\b","i");
themes[68]="cup";
photos[68]=["photo-restaurant-2.webp", "photo-dinner-2.webp"];
plans[69]={"title": "A noite no estúdio de TV", "file": "photo-restaurant-1.webp", "grammar": "Revisão: descrever pessoas e lugares com relativas", "goal": "Reveja who, which, that e where para descrever pessoas, coisas e lugares numa história.", "words": [["announcer", "apresentador"], ["producer", "produtor"], ["documentary", "documentário"], ["channel", "canal"]]};
content[69]=[[["Mia goes to the TV studio where her cousin works.", "A Mia vai ao estúdio de TV onde o primo dela trabalha."], ["He is the announcer who reads the evening news.", "Ele é o apresentador que lê o jornal da noite."], ["The channel which airs the show also has a documentary.", "O canal que exibe o programa também tem um documentário."], ["The producer that leads the show waves at Mia.", "O produtor que comanda o programa acena para a Mia."], ["Later, she finds him in the room where friends wait.", "Mais tarde, ela o encontra na sala onde os amigos esperam."]], [["Is this the studio where you work?", "Este é o estúdio onde você trabalha?"], ["Yes, and that is the desk where I speak.", "Sim, e aquela é a mesa onde eu falo."], ["Who is the producer that leads the show?", "Quem é o produtor que comanda o programa?"], ["He is the tall man who wears the red tie.", "É o homem alto que usa a gravata vermelha."], ["Is that the jacket which you bought?", "Essa é a jaqueta que você comprou?"], ["No, my aunt made it. She is a woman who loves sewing.", "Não, minha tia fez. Ela é uma mulher que adora costurar."], ["Are there seats where I can see well?", "Há lugares onde eu possa ver bem?"], ["Yes, take the seat that is near the desk.", "Sim, pegue o lugar que fica perto da mesa."]], ["Acento em actor e theater", "Em actor, a força está na primeira sílaba: /ˈæktər/. Em theater, o th inicial é /θ/ com a língua entre os dentes.", ["actor", "The actor is on stage."]], ["He is the actor ___ plays the king.", "who", "where", "Ele é o ator que faz o rei.", "Para pessoas, use who; where é para lugares."]];
patterns[69]=new RegExp("\\b(who|which|that|where) \\w+","i");
themes[69]="city";
photos[69]=["photo-ticketdesk-1.webp", "photo-square-1.webp"];
stories[69]=["O estúdio da Mia", "Mia is a girl who loves watching the news.~A Mia é uma menina que adora assistir ao jornal.|Her cousin Sam is an announcer who works every night.~O primo Sam é apresentador e trabalha todas as noites.|Tonight she goes to the studio where he reads the news.~Hoje à noite ela vai ao estúdio onde ele lê o jornal.|The man that sits next to her has a loud phone.~O homem que senta ao lado dela tem um celular barulhento.|It rings during the weather report which everyone loves.~Ele toca durante a previsão do tempo que todos adoram.|Mia asks the woman who works there for help.~A Mia pede ajuda à mulher que trabalha lá.|She takes the phone to the room where people wait.~Ela leva o celular à sala onde as pessoas esperam.|After the show, Sam thanks the girl who helped.~Depois do programa, o Sam agradece à menina que ajudou.|He shows her the jacket which he wears on the show.~Ele mostra a ela a jaqueta que usa no programa.|Mia smiles because it is her best night ever.~A Mia sorri porque é a melhor noite da vida dela."];
plans[70]={"title": "Planos para estudar", "file": "photo-study-1.webp", "grammar": "Verbo + infinitivo: want, hope, decide, plan", "goal": "Use want, hope, decide e plan seguidos de to + verbo para falar de desejos e planos.", "words": [["mathematics", "matemática"], ["geography", "geografia"], ["research", "pesquisa"], ["lab", "laboratório"]]};
content[70]=[[["Nico wants to pass the mathematics test in June.", "O Nico quer passar na prova de matemática em junho."], ["He decides to study every night after dinner.", "Ele decide estudar toda noite depois do jantar."], ["He hopes to do well in geography too.", "Ele espera ir bem em geografia também."], ["His sister plans to work in a lab after school.", "A irmã dele planeja trabalhar num laboratório depois da escola."], ["They both promise to help each other with homework.", "Os dois prometem se ajudar com a lição de casa."]], [["What do you want to study next year?", "O que você quer estudar no ano que vem?"], ["I hope to study geography, but I have not decided yet.", "Espero estudar geografia, mas ainda não decidi."], ["Do you plan to take the mathematics test this spring?", "Você planeja fazer a prova de matemática nesta primavera?"], ["Yes, I plan to ask a friend for help.", "Sim, planejo pedir ajuda a um amigo."], ["Did your brother decide to join the lab?", "Seu irmão decidiu entrar no laboratório?"], ["Yes, he wants to do some research before the trip.", "Sim, ele quer fazer uma pesquisa antes da viagem."], ["Do you hope to live abroad one day?", "Você espera morar no exterior um dia?"], ["I do, and I want to start soon.", "Espero, e quero começar logo."]], ["Reduzindo to em want to", "Na fala rápida, want to soa como wanna: o to vira um /tə/ curto e fraco.", ["want", "I want to study."]], ["Nico decides ___ every night.", "to study", "studying", "Nico decide estudar toda noite.", "Depois de decide, use to + verbo."]];
patterns[70]=new RegExp("\\b(want|wants|hope|hopes|decide|decides|decided|plan|plans) to\\b","i");
themes[70]="notebook";
photos[70]=["photo-study-1.webp", "photo-deskStudy-1.webp"];
plans[71]={"title": "Pedalando aos domingos", "file": "photo-door-1.webp", "grammar": "Verbo + -ing: enjoy, finish, mind, keep", "goal": "Use enjoy, finish, mind e keep seguidos de verbo com -ing.", "words": [["cycle", "pedalar"], ["babysit", "cuidar de crianças"], ["blog", "blog"], ["software", "programa de computador"]]};
content[71]=[[["Ava enjoys cycling to the park on Sundays.", "A Ava gosta de pedalar até o parque aos domingos."], ["She finishes cycling one loop before the rain starts.", "Ela termina uma volta de bicicleta antes de a chuva começar."], ["Then she keeps going and starts to cycle uphill.", "Depois ela continua e começa a pedalar morro acima."], ["Her neighbor does not mind coming to babysit.", "A vizinha dela não se importa de vir cuidar das crianças."], ["By six, Ava is tired but she enjoys writing her blog.", "Às seis, a Ava está cansada, mas gosta de escrever o blog dela."]], [["Do you enjoy cycling?", "Você gosta de pedalar?"], ["Yes, but I do not enjoy fixing the tires.", "Gosto, mas não gosto de consertar os pneus."], ["Did you finish writing your blog?", "Você terminou de escrever o seu blog?"], ["Not yet. I keep losing the right photos.", "Ainda não. Eu continuo perdendo as fotos certas."], ["Would you mind babysitting for me tonight?", "Você se importaria de cuidar das crianças por mim hoje à noite?"], ["Not at all. I do not mind helping.", "De jeito nenhum. Não me importo de ajudar."], ["Does your brother mind installing the software?", "Seu irmão se importa de instalar o programa?"], ["Yes, he keeps saying it is too slow.", "Sim, ele fica dizendo que é lento demais."]], ["O som /ŋ/ no final de -ing", "Em painting, o ing termina no nariz: a língua fica atrás e o g não é pronunciado.", ["painting", "I enjoy painting."]], ["Ben enjoys ___ the fence.", "painting", "to paint", "Ben gosta de pintar a cerca.", "Depois de enjoy, o verbo vai no -ing."]];
patterns[71]=new RegExp("\\b(enjoy|enjoys|finish|finishes|mind|keep|keeps|stops?) \\w+ing\\b|\\b(enjoy|enjoys|finish|finishes|keep|keeps|mind) \\w*ing\\b","i");
themes[71]="notebook";
