plans[72]={"title": "Hobbies no lago e na música", "file": "photo-parkPath-1.webp", "grammar": "Like, love, hate, prefer com -ing e com to", "goal": "Use like, love, hate e prefer com -ing ou com to + verbo para falar de gostos.", "words": [["singing", "canto"], ["fishing", "pesca"], ["diving", "mergulho"], ["photography", "fotografia"]]};
content[72]=[[["Ava loves singing in the car on warm days.", "A Ava adora cantar no carro nos dias quentes."], ["She likes fishing at the lake in spring.", "Ela gosta de pescar no lago na primavera."], ["She hates waiting for a big wave.", "Ela odeia esperar por uma onda grande."], ["Her husband prefers diving in calm water to singing.", "O marido prefere mergulhar em águas calmas a cantar."], ["Still, they both like to study photography on Sundays.", "Mesmo assim, os dois gostam de estudar fotografia aos domingos."]], [["Do you like singing in the shower?", "Você gosta de cantar no chuveiro?"], ["Yes, I love to sing in the morning.", "Sim, adoro cantar de manhã."], ["What do you enjoy on weekends?", "Do que você gosta nos fins de semana?"], ["I prefer fishing to staying at home.", "Prefiro pescar a ficar em casa."], ["Do you hate cooking when you are tired?", "Você odeia cozinhar quando está cansado?"], ["I do. I prefer to order a pizza.", "Odeio. Prefiro pedir uma pizza."], ["Does your sister like to learn photography?", "Sua irmã gosta de aprender fotografia?"], ["Yes, she loves taking photos of her dog.", "Sim, ela adora tirar fotos do cachorro dela."]], ["O ing final em singing e fishing", "Termine com som nasal, sem pronunciar o g: SÍN-guin sem g forte: SÍN-in, FÍ-chin.", ["fishing", "I love fishing."]], ["I prefer ___ at home to going out.", "staying", "stay", "Prefiro ficar em casa a sair.", "Depois de prefer ... to, usamos o verbo com -ing nos dois lados."]];
patterns[72]=new RegExp("\\b(like|likes|love|loves|hate|hates|prefer|prefers) (to )?\\w+(ing)?\\b","i");
