plans[73]={"title": "Se chover, vamos adiar", "file": "photo-dusk-1.webp", "grammar": "If + presente, will: primeira condicional", "goal": "Use if + presente simples e will + verbo para falar de uma possibilidade real no futuro.", "words": [["postpone", "adiar"], ["emergency", "emergência"], ["risk", "risco"], ["warn", "avisar"]]};
content[73]=[[["If there is a storm, Peg will postpone the trip.", "Se houver tempestade, a Peg vai adiar a viagem."], ["If it rains hard, we will stay at school.", "Se chover forte, vamos ficar na escola."], ["Tina says, \"If there is a risk, I will warn everyone.\"", "A Tina diz: “Se houver risco, vou avisar todo mundo.”"], ["If Ravi sees smoke, he will call the emergency number.", "Se o Ravi vir fumaça, ele vai ligar para o número de emergência."], ["If the weather is good, they will leave at noon.", "Se o tempo estiver bom, eles vão sair ao meio-dia."]], [["What will you do if it rains tomorrow?", "O que você vai fazer se chover amanhã?"], ["If it rains, I will watch a movie at home.", "Se chover, vou assistir a um filme em casa."], ["Will you call me if there is an emergency?", "Você me liga se houver uma emergência?"], ["Yes, I will call you right away.", "Sim, ligo para você na mesma hora."], ["If the road is closed, will they postpone the trip?", "Se a estrada estiver fechada, eles vão adiar a viagem?"], ["I think so. They will tell us by text.", "Acho que sim. Eles vão nos avisar por mensagem."], ["If you call me, I will answer right away.", "Se você me ligar, eu atendo na hora."], ["Good. I will call you at nine.", "Ótimo. Ligo para você às nove."]], ["A contração I will e o 'll", "Na fala, I will vira I'll, curtinho: /aɪl/. Em will, o w pede os lábios arredondados.", ["will", "If it rains, I will stay."]], ["If it rains, we ___ at home.", "will stay", "stay", "Se chover, vamos ficar em casa.", "Na primeira condicional, o resultado usa will + verbo."]];
patterns[73]=new RegExp("\\bif .*\\bwill\\b|\\bwill .*\\bif\\b","i");
themes[73]="city";
photos[73]=["photo-dusk-1.webp", "photo-street-1.webp"];
plans[74]={"title": "Passeio, a menos que chova", "file": "photo-lake-2.webp", "grammar": "Unless e when em frases condicionais simples", "goal": "Use unless para dizer a menos que e when para dizer quando em planos simples.", "words": [["dam", "represa"], ["log", "tronco"], ["boot", "bota"], ["rough", "difícil, áspero"]]};
content[74]=[[["Lia and Ben will walk to the dam unless it rains.", "A Lia e o Ben vão andar até a represa, a menos que chova."], ["They will sit on a log when the sun comes up.", "Eles vão sentar num tronco quando o sol nascer."], ["Unless Ben finds his other boot, they will stay home.", "A menos que o Ben ache a outra bota, eles ficam em casa."], ["When the food is ready, Lia calls her cousin.", "Quando a comida fica pronta, a Lia chama a prima."], ["They will stay until Sunday unless it gets cold.", "Eles ficam até domingo, a menos que esfrie."]], [["Are we going to the dam on Saturday?", "Vamos à represa no sábado?"], ["Yes, unless the weather changes.", "Vamos, a menos que o tempo mude."], ["What will you do when you get there?", "O que você vai fazer quando chegar lá?"], ["I will sit on a log when we arrive.", "Vou sentar num tronco quando chegarmos."], ["Will you call me when you are ready to start?", "Você me chama quando estiver pronto para começar?"], ["I will, unless my phone has no battery.", "Chamo, a menos que meu celular fique sem bateria."], ["Will they join us unless they have work?", "Eles vão se juntar a nós, a menos que tenham trabalho?"], ["Yes, they will come when they finish at two.", "Vão, quando terminarem às duas."]], ["O som /ʌ/ em unless e Sunday", "Em unless e Sunday, a vogal é curta e relaxada, entre o a e o e do português: /ʌ/.", ["unless", "Unless it rains, we go."]], ["We will go ___ it rains.", "unless", "if not", "Vamos a menos que chova.", "Unless significa a menos que: ele já carrega a ideia de negação."]];
patterns[74]=new RegExp("\\b(unless|when) \\w+","i");
themes[74]="park";
