plans[75]={"title": "Gelo derrete, água ferve", "file": "photo-coffeeTable-1.webp", "grammar": "Zero conditional: If you heat ice, it melts", "goal": "Use if + presente e presente para falar de fatos e hábitos que sempre acontecem.", "words": [["boil", "ferver"], ["solid", "sólido"], ["frozen", "congelado"], ["dissolve", "dissolver"]]};
content[75]=[[["If you heat ice, it melts.", "Se você aquece gelo, ele derrete."], ["When water gets very hot, it starts to boil.", "Quando a água fica muito quente, ela começa a ferver."], ["If food is frozen, it stays good for months.", "Se a comida está congelada, ela se conserva por meses."], ["If Noah adds sugar to his tea, it dissolves.", "Se o Noah põe açúcar no chá, ele se dissolve."], ["Noah always uses cold water if he makes lemon juice.", "O Noah sempre usa água fria se faz suco de limão."]], [["What happens if you leave ice in the sun?", "O que acontece se você deixa gelo no sol?"], ["It melts, and you get water.", "Derrete, e você fica com água."], ["What happens when water gets to one hundred degrees?", "O que acontece quando a água chega a cem graus?"], ["It boils, and it is very hot.", "Ela ferve, e fica muito quente."], ["If I put sugar in cold water, does it dissolve?", "Se eu pôr açúcar em água fria, ele dissolve?"], ["Yes, but it takes more time than in hot water.", "Sim, mas leva mais tempo do que em água quente."], ["Is ice a solid, or is it water?", "O gelo é um sólido ou é água?"], ["It is a solid, but it melts if you heat it.", "É um sólido, mas derrete se você o aquece."]], ["O som /z/ final em boils e melts", "Termine com um zumbido de voz, como no “z” de zero: bóilz. Em melts, o /s/ final é surdo: mélts.", ["boils", "Water boils at one hundred degrees."]], ["If you heat ice, it ___.", "melts", "will melts", "Se você esquenta gelo, ele derrete.", "No zero conditional, os dois verbos ficam no presente simples."]];
patterns[75]=new RegExp("\\b(if|when) [^,.?]*,? .*","i");
themes[75]="cup";
