plans[76]={"title": "Trabalhar para viajar", "file": "photo-payment-1.webp", "grammar": "So that e to + verbo para explicar o objetivo", "goal": "Use to + verbo ou so that + frase para explicar o objetivo de uma ação.", "words": [["afford", "ter condição de pagar"], ["earn", "ganhar (dinheiro)"], ["allowance", "mesada"], ["waste", "desperdiçar"]]};
content[76]=[[["Ravi works on Saturdays so that he can afford a trip.", "O Ravi trabalha aos sábados para poder pagar uma viagem."], ["He wants to earn extra money to buy a cheap ticket.", "Ele quer ganhar um dinheiro extra para comprar uma passagem barata."], ["He cooks at home so that he does not waste money.", "Ele cozinha em casa para não desperdiçar dinheiro."], ["He walks to work to avoid paying for the bus.", "Ele vai a pé ao trabalho para evitar pagar o ônibus."], ["In June, he buys a cheap ticket to Chicago.", "Em junho, ele compra uma passagem barata para Chicago."]], [["Why do you work on weekends?", "Por que você trabalha nos fins de semana?"], ["I work so that I can afford a new phone.", "Trabalho para poder pagar um celular novo."], ["Why did you ask for a bigger allowance?", "Por que você pediu uma mesada maior?"], ["I asked for it so that I can buy a ticket.", "Pedi para poder comprar uma passagem."], ["Why does Ben work on Saturdays?", "Por que o Ben trabalha aos sábados?"], ["He works so that he can buy a new bike.", "Ele trabalha para poder comprar uma bicicleta nova."], ["Why are you earning extra money?", "Por que você está ganhando um dinheiro extra?"], ["To visit my grandmother in Texas next summer.", "Para visitar minha avó no Texas no próximo verão."]], ["Entonação em Why...? e To...", "A pergunta com Why sobe e desce no fim; a resposta com To... começa mais baixa e é curta.", ["afford", "I cannot afford a car."]], ["He walks to work ___ he can save money.", "so that", "for that", "Ele vai a pé ao trabalho para poder economizar dinheiro.", "So that liga o objetivo a uma frase completa."]];
patterns[76]=new RegExp("\\bso that\\b|\\bto (?:afford|buy|visit|get|keep|avoid|spend)\\b","i");
themes[76]="ticket";
photos[76]=["photo-payment-1.webp", "photo-ticketdesk-2.webp"];
plans[77]={"title": "Onde fica a plataforma?", "file": "photo-stationSign-1.webp", "grammar": "Perguntas indiretas simples: Do you know where…?", "goal": "Use Do you know where, what time ou how much para fazer uma pergunta educada, sem inverter o verbo.", "words": [["directions", "indicações"], ["destination", "destino"], ["arrival", "chegada"], ["transport", "transporte"]]};
content[77]=[[["Lou is at the station and cannot find her train.", "A Lou está na estação e não encontra o trem dela."], ["She asks a woman, \"Do you know where the platform is?\"", "Ela pergunta a uma mulher: “Você sabe onde fica a plataforma?”"], ["The woman does not know when the train leaves.", "A mulher não sabe quando o trem sai."], ["Lou follows the directions on the wall to her platform.", "A Lou segue as indicações na parede até a plataforma dela."], ["She asks a guard when she will reach her destination.", "Ela pergunta a um guarda quando vai chegar ao destino."]], [["Excuse me, do you know where platform four is?", "Com licença, você sabe onde fica a plataforma quatro?"], ["Yes, it is down the stairs on the left.", "Sim, é descendo a escada, à esquerda."], ["Can you tell me what time the train leaves?", "Pode me dizer a que horas o trem sai?"], ["I am not sure. Let us check the schedule.", "Não tenho certeza. Vamos ver o horário."], ["Do you know what time the arrival will be?", "Você sabe a que horas será a chegada?"], ["Yes, it will be twenty minutes late today.", "Sim, vai ser com vinte minutos de atraso hoje."], ["Could you tell me how much public transport costs here?", "Pode me dizer quanto custa o transporte público aqui?"], ["It costs eleven dollars for the whole day, I think.", "Custa onze dólares o dia todo, acho."]], ["Ritmo de Do you know...?", "Una do you know em um bloco só: /dʒuˈnoʊ/. A voz sobe no final da pergunta.", ["platform", "Where is the platform?"]], ["Do you know where the platform ___?", "is", "is it", "Você sabe onde fica a plataforma?", "Em pergunta indireta, o verbo vem depois do sujeito, como numa afirmação."]];
patterns[77]=new RegExp("\\b(do you know|can you tell me|could you tell me) (where|what|how|if)\\b|\\b(knows?|know) (what|how|if|where)\\b","i");
themes[77]="map";
photos[77]=["photo-stationSign-1.webp", "photo-train-1.webp"];
plans[78]={"title": "O que você acha do filme?", "file": "photo-message-1.webp", "grammar": "Pedir e dar opiniões: I think, I do not think, in my opinion", "goal": "Use I think, I do not think e in my opinion para dar e pedir opiniões com educação.", "words": [["ending", "final"], ["opinion", "opinião"], ["critic", "crítico"], ["romance", "romance"]]};
content[78]=[[["Tina reads what a critic wrote about the new movie.", "A Tina lê o que um crítico escreveu sobre o filme novo."], ["In my opinion, the ending is the best part.", "Na minha opinião, o final é a melhor parte."], ["Her friend Nico thinks the romance is boring.", "O amigo dela, o Nico, acha o romance chato."], ["I do not think so, says Tina with a smile.", "Não acho, diz a Tina com um sorriso."], ["They agree that the music is great.", "Eles concordam que a música é ótima."]], [["What do you think of the movie?", "O que você acha do filme?"], ["I think it is great, but a little long.", "Acho ótimo, mas um pouco longo."], ["Do you think the ending is good?", "Você acha que o final é bom?"], ["No, I do not think it is very clear.", "Não, acho que não é muito claro."], ["What is your opinion of the actor?", "Qual é a sua opinião sobre o ator?"], ["In my opinion, he is the best one in the film.", "Na minha opinião, ele é o melhor do filme."], ["Do you think I should trust the critic?", "Você acha que devo confiar no crítico?"], ["Yes, I think he is usually right.", "Sim, acho que ele geralmente acerta."]], ["Entonação em I think...", "Em I think, a voz sobe um pouco em think e desce no fim da frase. O th é /θ/, com a língua entre os dentes.", ["opinion", "In my opinion, it is good."]], ["I ___ the ending is good.", "think", "am think", "Eu acho que o final é bom.", "Em inglês, diga I think, sem o verbo to be."]];
patterns[78]=new RegExp("\\b(I think|I do not think|in my opinion|do you think)\\b|\\bthinks\\b","i");
themes[78]="chat";
photos[78]=["photo-friends-1.webp", "photo-message-1.webp"];
plans[79]={"title": "A viagem do Ravi", "file": "photo-railpass-1.webp", "grammar": "Revisão do bloco: planos, condições e experiências", "goal": "Reveja verbos com infinitivo e -ing, condicionais, so that e perguntas indiretas numa história.", "words": [["boarding", "embarque"], ["overseas", "no exterior"], ["border", "fronteira"], ["attendant", "atendente"]]};
content[79]=[[["Ravi plans to fly overseas to see his aunt.", "O Ravi planeja voar para o exterior para ver a tia."], ["If he forgets his passport, he will miss the flight.", "Se ele esquecer o passaporte, vai perder o voo."], ["He keeps checking his bag so that nothing is missing.", "Ele continua conferindo a mala para que nada falte."], ["He asks an attendant, \"Do you know where my gate is?\"", "Ele pergunta a um atendente: “Você sabe onde fica o meu portão?”"], ["In his opinion, boarding the plane is the best part.", "Na opinião dele, embarcar no avião é a melhor parte."]], [["Do you want to come to the airport with me?", "Você quer ir ao aeroporto comigo?"], ["Yes, I will help with your luggage.", "Quero, vou ajudar com a sua bagagem."], ["Did you pack your passport?", "Você guardou o passaporte na mala?"], ["Yes, I put it in my coat so that I will not lose it.", "Sim, pus no casaco para não perder."], ["Do you know what time we need to leave?", "Você sabe a que horas precisamos sair?"], ["If the traffic is bad, we will leave at six.", "Se o trânsito estiver ruim, saímos às seis."], ["Do you think the border check will be long?", "Você acha que a conferência na fronteira vai demorar?"], ["I think it will be quick. I keep my papers ready.", "Acho que vai ser rápida. Deixo meus papéis prontos."]], ["Acento em airport e passport", "Nas duas palavras a força cai na primeira sílaba: /ˈɛrpɔrt/ e /ˈpæspɔrt/.", ["passport", "Show your passport, please."]], ["If he forgets it, he ___ the flight.", "will miss", "misses will", "Se ele esquecer, vai perder o voo.", "Primeira condicional: if + presente e will + verbo."]];
patterns[79]=new RegExp("\\b(if|so that|do you know|I think|I enjoy|plans to|want to)\\b","i");
themes[79]="ticket";
photos[79]=["photo-railpass-1.webp", "photo-luggage-1.webp"];
stories[79]=["A viagem do Ravi", "Ravi plans to visit his aunt overseas next June.~O Ravi planeja visitar a tia no exterior em junho.|He wants to leave early so that he can relax.~Ele quer sair cedo para poder relaxar.|If he forgets his passport, he will miss the flight.~Se esquecer o passaporte, ele vai perder o voo.|At home, he keeps checking his bag again and again.~Em casa, ele confere a mala de novo e de novo.|At the airport, he asks where the right gate is.~No aeroporto, ele pergunta onde fica o portão certo.|An attendant who works there shows him the boarding line.~Um atendente que trabalha lá mostra a ele a fila de embarque.|He enjoys sitting near the window and watching planes.~Ele gosta de sentar perto da janela e ver os aviões.|When the plane lands, he calls his aunt.~Quando o avião pousa, ele liga para a tia.|She waits at the station where they always meet.~Ela espera na estação onde eles sempre se encontram.|Ravi thinks the trip is the best surprise of June.~O Ravi acha que a viagem é a melhor surpresa de junho."];
